# ── SolarEdge / RenoGrid ───────────────────────────────────────────────────────
SE_BASE          = "https://monitoring.solaredge.com"
SE_COOKIE_RT_KEY = "se_cookie"   # chave no tokens_runtime.json (era se_cookie.txt)
SE_CREDS_PATH    = os.path.join(_AQUI, "se_credentials.txt")
SE_COGNITO_POOL  = os.environ.get("SE_COGNITO_POOL",   "eu-central-1_fVUTz39em")
SE_COGNITO_CLIENT= os.environ.get("SE_COGNITO_CLIENT", "ugfnsujd3384sshcjehaphlh3")
SE_STRING_MIN_W  = 0.0      # potência (W) mínima p/ considerar a string "ativa" (> que isso)
SE_OPT_MIN_W     = 0.0      # idem p/ otimizador (painel)
_se_cookie       = {"token": "", "exp": 0.0}
_se_login_lock   = threading.Lock()
_se_cache        = {"payload": None, "ts": 0.0}

def _se_credentials():
    u = os.environ.get("SE_USERNAME", ""); p = os.environ.get("SE_PASSWORD", "")
    if u and p:
        return u, p
    try:
        with open(SE_CREDS_PATH, encoding="utf-8") as f:
            lines = [ln.strip() for ln in f if ln.strip()]
        return lines[0], lines[1]
    except Exception:
        return "", ""


def _jwt_exp(token: str) -> float:
    import base64
    try:
        p = token.split(".")[1]; p += "=" * (-len(p) % 4)
        return float(json.loads(base64.urlsafe_b64decode(p)).get("exp", 0))
    except Exception:
        return 0.0


def _se_login() -> str:
    """Login SRP no AWS Cognito → access_token fresco (= cookie se_monitoring_auth)."""
    from pycognito import Cognito
    user, pw = _se_credentials()
    if not (user and pw):
        raise RuntimeError("credenciais SolarEdge ausentes (se_credentials.txt / SE_USERNAME+SE_PASSWORD)")
    c = Cognito(SE_COGNITO_POOL, SE_COGNITO_CLIENT, username=user)
    c.authenticate(password=pw)
    _se_cookie["token"] = c.access_token
    _se_cookie["exp"]   = _jwt_exp(c.access_token)
    try:   # persiste p/ fallback
        _tokens_rt_set(SE_COOKIE_RT_KEY, f"se_monitoring_auth={c.access_token}")
    except Exception:
        pass
    mins = int((_se_cookie["exp"] - time.time()) / 60)
    print(f"[SolarEdge] token renovado via Cognito (válido por ~{mins} min)")
    return c.access_token


def _get_se_cookie() -> str:
    """Cookie SolarEdge — renova automaticamente via Cognito quando expira."""
    tok, exp = _se_cookie.get("token"), _se_cookie.get("exp", 0)
    if tok and time.time() < exp - 120:
        return f"se_monitoring_auth={tok}"
    with _se_login_lock:
        tok, exp = _se_cookie.get("token"), _se_cookie.get("exp", 0)
        if tok and time.time() < exp - 120:        # outro thread já renovou
            return f"se_monitoring_auth={tok}"
        try:
            return f"se_monitoring_auth={_se_login()}"
        except Exception as e:
            print(f"[SolarEdge] login automático falhou: {e}")
    # Fallback: último cookie persistido (se houver)
    return _tokens_rt_get(SE_COOKIE_RT_KEY)


def _se_headers() -> dict:
    return {
        "accept": "application/json, text/plain, */*",
        "content-type": "application/json",
        "origin": SE_BASE,
        "referer": f"{SE_BASE}/one",
        "user-agent": "Mozilla/5.0",
        "cookie": _get_se_cookie(),
    }


# ── Cadastro mestre: BD_Performance, aba "Equipamentos" ───────────────────────
# Fonte ÚNICA do cadastro (substitui a antiga planilha "Check Diário"):
#   • Usina / Usina Supervisório         → nome de exibição da usina (USINA_DISPLAY)
#   • Equipamento / Equip. Supervisório  → nome de exibição por inversor (EQUIP_NAMES)
#   • Strings Ativas                     → esperadas por inversor (ESPERADO_INV / ESPERADO)
#   • Full O&M                           → conjunto de usinas Full O&M (FULL_OM)
#   • Potência (kWp)                     → potência por inversor (POWER_INV)
# As chaves supervisório são exatamente os nomes que cada API usa (plant['nome'] / device_name).
# 100% API (decisão do Levi, 25/08): as planilhas NÃO vêm mais do OneDrive. A fonte da verdade é
# a Gridco Performance API, materializada no espelho `bases/` pelo `_bd_api_loop` (30 min). Os
# caminhos do OneDrive foram REMOVIDOS de propósito — mantê-los "por garantia" faria a plataforma
# voltar a ler o arquivo sincronizado em silêncio sempre que o espelho atrasasse, e as duas fontes
# divergem de formas difíceis de notar (cache de fórmula, lock do Excel, sync sobrescrevendo).
# A env BD_PERF_PATH continua valendo para emergência/diagnóstico.
_BD_PERF_ONLINE_CANDS = [p for p in [os.environ.get("BD_PERF_PATH")] if p]
_BD_PERF_LOCAL = os.path.join(_AQUI, "BD_Performance.xlsx")

# ── Espelho local das planilhas (servidor SEM OneDrive) ───────────────────────
# No PC dedicado o OneDrive não fica montado: sincronizar arquivo numa máquina exposta é
# justamente o que queremos evitar. Quem tem o OneDrive empurra as planilhas para cá por
# HTTPS (ver push_bases.py e POST /api/admin/base/<nome>).
# A ORDEM importa: o OneDrive continua ganhando ONDE EXISTE, e o espelho assume só onde não
# existe. Assim o mesmo código serve a máquina do analista e o servidor, sem variável de
# ambiente e sem risco de servir espelho velho enquanto a fonte viva está disponível.
_BASES_DIR = os.path.join(_AQUI, "bases")


def _base_espelho(nome_arquivo: str):
    """Caminho no espelho, se o arquivo já tiver sido empurrado para lá."""
    p = os.path.join(_BASES_DIR, nome_arquivo)
    return p if os.path.exists(p) else None


def _bd_perf_path() -> str:
    """Caminho do BD_Performance — prioridade: (1) versão ONLINE do OneDrive;
    (2) espelho recebido por push; (3) cópia local. Reavaliado a cada carga."""
    for p in _BD_PERF_ONLINE_CANDS:
        if os.path.exists(p):
            return p
    return _base_espelho("BD_Performance.xlsx") or _BD_PERF_LOCAL


_BD_TMP = os.path.join(tempfile.gettempdir(), "bd_perf_dashboard.xlsx")
_bd_copia = {"key": None, "path": None}     # cópia viva do BD_Performance, por VERSÃO do arquivo
_bd_copia_lock = threading.Lock()


def _bd_readable_path():
    """Caminho LEGÍVEL do BD_Performance: devolve uma CÓPIA local (contorna o lock do
    Excel/OneDrive quando o arquivo está aberto). O mtime do cache continua vindo do original.

    A cópia é feita UMA VEZ POR VERSÃO (mtime+tamanho) e reaproveitada — antes era um
    `shutil.copy2` de vários MB a CADA chamada, e sempre para o MESMO caminho fixo: com dois
    usuários simultâneos, uma thread truncava/reescrevia o arquivo enquanto a outra estava
    lendo com openpyxl (leitura vazia, xlsx corrompido, processo caindo). Cada versão ganha
    seu próprio nome, então quem já está lendo a anterior nunca tem o arquivo puxado do pé."""
    src = _bd_perf_path()
    try:
        st = os.stat(src)
    except Exception:
        return src
    key = (src, st.st_mtime, st.st_size)
    ent = _bd_copia                                   # leitura sem lock (dict é atômico o bastante)
    if ent["key"] == key and ent["path"] and os.path.exists(ent["path"]):
        return ent["path"]
    with _bd_copia_lock:
        if _bd_copia["key"] == key and _bd_copia["path"] and os.path.exists(_bd_copia["path"]):
            return _bd_copia["path"]                  # outra thread já copiou esta versão
        novo = f"{_BD_TMP[:-5]}.{int(st.st_mtime)}.xlsx"
        try:
            if not os.path.exists(novo):
                shutil.copy2(src, novo)
        except Exception:
            return src
        antigo = _bd_copia["path"]
        _bd_copia.update({"key": key, "path": novo})
        if antigo and antigo != novo:
            try:
                os.remove(antigo)                     # no Windows falha se alguém ainda lê → ok
            except Exception:
                pass
        return novo

# Globais preenchidas por load_equipamentos() (recarregáveis em runtime)
ESPERADO_INV  = {}   # {usina_sup: {equip_sup: strings_esperadas}}
EQUIP_NAMES   = {}   # {usina_sup: {equip_sup: equipamento_display}}
USINA_DISPLAY = {}   # {usina_sup: usina_display}
USINA_GRUPO   = {}   # {usina_sup: usina_fisica} — SEM dedup; agrupa sub-usinas (Indaiatuba 1-4 → "Indaiatuba")
ESPERADO      = {}   # {usina_sup: {"inv_esp": n, "str_esp": soma}}
FULL_OM       = set()
STRING_BOX    = set()   # {usina_sup}  usinas com coluna "String Box"=Sim (sem visão por string)
POWER_INV     = {}   # {usina_sup: {alias_norm: potencia_kwp}}  alias = equip_sup e display
POWER_UFV     = {}   # {usina_sup: potencia_kwp}  linha Equipamento="UFV" (potência da USINA inteira)
FULL_OM_DISP  = set()   # {nrm(usina EXIBIÇÃO)} Full O&M — o FULL_OM é por supervisório, e usina Thopen
                        # costuma ter esse campo VAZIO (some do set). Este casa pelo nome de exibição.
POWER_INV_DISP = {}     # {nrm(usina EXIBIÇÃO): {nrm(equipamento): kwp}} — mesmo motivo do FULL_OM_DISP.
                        # É o que permite o PR por inversor da Thopen (aba do BD_Thopen × potência daqui).
_bd_mtime     = 0.0
_bd_lock      = threading.Lock()


def _nrm(s) -> str:
    return re.sub(r"\s+", "", str(s)).strip().lower()


def load_equipamentos():
    """(Re)carrega TODO o cadastro a partir da aba 'Equipamentos' do BD_Performance:
    esperadas (Strings Ativas), nomes de exibição, Full O&M e potência por inversor.
    Chamada na init e sempre que o arquivo muda (mtime). Uma só leitura alimenta tudo."""
    global ESPERADO_INV, EQUIP_NAMES, USINA_DISPLAY, USINA_GRUPO, ESPERADO, FULL_OM, STRING_BOX, POWER_INV, POWER_UFV, FULL_OM_DISP, POWER_INV_DISP, _bd_mtime
    try:
        path = _bd_perf_path()
        df = pd.read_excel(_bd_readable_path(), sheet_name="Equipamentos", header=2)
        df.columns = [str(c).strip() for c in df.columns]
        # ABA SEM CABEÇALHO PRECISA FALHAR ALTO. Estes cinco usavam `next()` SEM default, e um
        # `StopIteration` tem str() VAZIA: o except lá embaixo imprimia "não carregado: " e mais
        # nada, com o cadastro INTEIRO ficando vazio em silêncio. Foi o que aconteceu entre 25 e
        # 26/08 — o espelho da API veio sem a linha de cabeçalho na Equipamentos, o `header=2`
        # caiu em linha vazia, tudo virou "Unnamed", e a plataforma rodou um dia com ESPERADO_INV,
        # FULL_OM, POWER_INV e USINA_DISPLAY zerados (146 usinas na tela, "strings esperadas" em
        # branco em todas as fontes). Com a mensagem explícita, o mesmo acidente vira uma linha
        # de log que se lê. Ver [[migracao-onedrive-para-api-planilhas]].
        def _col(pred, rotulo):
            c = next((c for c in df.columns if pred(c)), None)
            if c is None:
                raise RuntimeError(
                    f"aba Equipamentos sem a coluna {rotulo} — achei {list(df.columns)[:6]}... "
                    f"(cabeçalho fora do lugar? o leitor espera na linha 3 de {_bd_perf_path()})")
            return c

        c_us   = _col(lambda c: "supervis" in c.lower() and "usina" in c.lower(), "'Usina Supervisório'")
        c_usd  = _col(lambda c: c.lower() == "usina", "'Usina'")
        c_es   = _col(lambda c: "supervis" in c.lower() and "equip" in c.lower(), "'Equipamento Supervisório'")
        c_eq   = _col(lambda c: c.lower() == "equipamento", "'Equipamento'")
        c_pot  = _col(lambda c: c.lower().startswith("pot"), "de potência")
        c_full = next((c for c in df.columns if "full" in c.lower()), None)
        c_sa   = next((c for c in df.columns if "string" in c.lower() and "ativ" in c.lower()), None)
        c_sb   = next((c for c in df.columns if "string" in c.lower() and "box" in c.lower()), None)

        esperado_inv, equip_names, usina_display, power_inv = {}, {}, {}, {}
        power_ufv = {}                       # potência da USINA (linha Equipamento = "UFV")
        full_om_disp = set()                 # Full O&M pelo nome de EXIBIÇÃO (pega usina sem supervisório)
        power_inv_disp = {}                  # potência por inversor pelo nome de EXIBIÇÃO (idem)
        full_om, string_box = set(), set()
        for _, row in df.iterrows():
            # Potência da USINA INTEIRA (linha Equipamento = "UFV") — p/ estimar perda de geração em
            # parada total (religamento/corretiva). Fica ANTES do guard de supervisório porque MUITAS
            # usinas (ex.: Sítio dos Nogueiras) só preenchem a coluna "Usina" nessa linha. Indexada
            # pelos DOIS nomes (supervisório e exibição) — a planilha usa ora um, ora outro.
            # Full O&M pelo nome de EXIBIÇÃO — ANTES do guard de supervisório, pelo mesmo motivo do UFV:
            # muita usina Thopen tem o supervisório vazio e sumiria do FULL_OM.
            if c_full and str(row[c_full]).strip().lower() == "sim" and pd.notna(row[c_usd]):
                full_om_disp.add(_nrm(row[c_usd]))
            # Potência por INVERSOR pelo nome de exibição — habilita o PR por inversor da Thopen.
            if (pd.notna(row[c_usd]) and pd.notna(row[c_eq])
                    and str(row[c_eq]).strip().lower().startswith("inversor")):
                try:
                    _pki = float(row[c_pot])
                except (TypeError, ValueError):
                    _pki = None
                if _pki and _pki > 0:
                    power_inv_disp.setdefault(_nrm(row[c_usd]), {})[_nrm(row[c_eq])] = _pki
            _eq0 = row[c_eq]
            if pd.notna(_eq0) and str(_eq0).strip().upper() == "UFV":
                try:
                    _pu = float(row[c_pot])
                except (TypeError, ValueError):
                    _pu = None
                if _pu and _pu > 0:
                    for _al in (row[c_us], row[c_usd]):
                        if pd.notna(_al) and str(_al).strip():
                            power_ufv[_nrm(_al)] = _pu
            # "Usina Supervisório" VAZIA não pode descartar a linha — o nome da usina já identifica.
            # Tucano 1/2 têm potência (334,63 kWp) e 20 strings por inversor na planilha, mas caíam
            # fora do cadastro inteiro por causa desta coluna em branco; sem potência, o PR por
            # inversor sai nulo e a UFV some do gráfico de PR (Levi, 30/07: "só ter o nome da usina
            # e os dados coletados já é para aparecer"). A chave supervisório continua preferida —
            # é ela que casa com o nome que cada API devolve —, o display entra só como reserva.
            _sup = str(row[c_us]).strip() if pd.notna(row[c_us]) else ""
            _dsp = str(row[c_usd]).strip() if pd.notna(row[c_usd]) else ""
            if not _sup and not _dsp:
                continue
            us = _sup or _dsp
            # Nome de exibição da usina (dedup de nomes ambíguos é feito depois)
            if pd.notna(row[c_usd]):
                ud = str(row[c_usd]).strip()
                if ud:
                    usina_display[us] = ud
            # Full O&M e String Box — marcados por linha, consistentes por usina
            if c_full and str(row[c_full]).strip().lower() == "sim":
                full_om.add(us)
            if c_sb and str(row[c_sb]).strip().lower() == "sim":
                string_box.add(us)
            # Daqui pra baixo: só inversores individuais
            eq = row[c_eq]
            if pd.isna(eq) or not str(eq).strip().lower().startswith("inversor"):
                continue
            eq = str(eq).strip()
            es = str(row[c_es]).strip() if pd.notna(row[c_es]) else None
            # Potência (kWp) — indexada por equip_sup e display (ambas chaves possíveis da API)
            try:
                pk = float(row[c_pot])
            except (TypeError, ValueError):
                pk = None
            if pk is not None:
                d = power_inv.setdefault(us, {})
                for alias in (es, eq):
                    if alias:
                        d[_nrm(alias)] = pk
            # Esperadas (Strings Ativas) + nome de exibição — chaveados por equip_sup (chave da API)
            if es:
                equip_names.setdefault(us, {})[es] = eq
                if c_sa is not None and pd.notna(row[c_sa]):
                    try:
                        esperado_inv.setdefault(us, {})[es] = int(round(float(row[c_sa])))
                    except (TypeError, ValueError):
                        pass

        # Mapa p/ AGRUPAR sub-usinas (Indaiatuba 1-4, Ceilândia II - *, Céu Azul I/II/III…) pela
        # usina física — guardado ANTES da dedup abaixo (que descarta justamente os agrupados).
        usina_grupo = dict(usina_display)
        # Remove nomes de exibição AMBÍGUOS (mesmo display p/ vários supervisórios, ex.: "Altair" x5).
        # A entrada IDÊNTICA (sup == display) não conta como concorrente: ela não traduz nada, e
        # nasce da linha sem "Usina Supervisório" (que agora entra pelo nome da usina). Sem esta
        # ressalva, a linha "UFV" do Tucano — sem supervisório — criava a chave "Tucano 1"→"Tucano 1"
        # e fazia o de-para REAL ("UFV Tucano"→"Tucano 1") parecer duplicado; o Levi preenchia a
        # planilha certo e a usina continuava aparecendo com o nome cru da API (31/07).
        _disp_count = {}
        for _s, _d in usina_display.items():
            if _s != _d:                       # só traduções de verdade disputam o nome
                _disp_count[_d] = _disp_count.get(_d, 0) + 1
        _ambiguos = sum(1 for s, v in usina_display.items() if s != v and _disp_count.get(v, 0) > 1)
        usina_display = {sup: disp for sup, disp in usina_display.items()
                         if sup == disp or _disp_count.get(disp, 0) == 1}
        if _ambiguos:
            print(f"[AVISO] {_ambiguos} usinas com nome de exibição duplicado na planilha — "
                  f"mantido o nome supervisório/API nessas (evita ambiguidade)")

        # Totais por usina (nível usina)
        esperado = {us: {"inv_esp": len(eq), "str_esp": sum(eq.values())}
                    for us, eq in esperado_inv.items()}

        # Publica de uma vez (substitui as globais)
        ESPERADO_INV, EQUIP_NAMES, USINA_DISPLAY = esperado_inv, equip_names, usina_display
        USINA_GRUPO = usina_grupo
        ESPERADO, FULL_OM, STRING_BOX, POWER_INV = esperado, full_om, string_box, power_inv
        POWER_UFV, FULL_OM_DISP, POWER_INV_DISP = power_ufv, full_om_disp, power_inv_disp
        # CADASTRO VAZIO NÃO CARIMBA O MTIME. No reboot de 26/08 o app subiu às 07:54, antes de
        # o OneDrive hidratar os arquivos: a leitura "deu certo" com ZERO usinas, o mtime foi
        # carimbado como sucesso e a recarga automática (que compara mtime) passou a achar que
        # estava tudo em dia — o portão Full O&M ficou desligado (146 usinas na tela, cadastro
        # inteiro vazio) até alguém reiniciar. Sem o carimbo, o ciclo seguinte do worker relê.
        if not full_om and not esperado_inv:
            print("[FALHA] BD_Performance/Equipamentos veio VAZIO (arquivo ainda não hidratado?) — "
                  "não carimbo o mtime; o próximo ciclo tenta de novo.")
            return
        try:
            _bd_mtime = os.path.getmtime(path)
        except OSError:
            _bd_mtime = 0.0
        _n_pot = sum(len(v) for v in power_inv.values())
        _src = ("LOCAL (fallback)" if path == _BD_PERF_LOCAL
                else "ESPELHO/API" if os.path.dirname(path) == _BASES_DIR else "ENV")
        print(f"[OK] BD_Performance/Equipamentos [{_src}]: {len(esperado_inv)} usinas c/ esperadas | "
              f"{len(FULL_OM)} Full O&M | {len(STRING_BOX)} String Box | {_n_pot} aliases de potência | "
              f"{len(power_ufv)} aliases de potência UFV")
    except Exception as e:
        print(f"[AVISO] BD_Performance (Equipamentos) não carregado: {e}")


def _pot_ufv(nome):
    """Potência (kWp) da USINA pelo cadastro (Equipamentos, linha Equipamento='UFV'). Aceita nome
    supervisório OU de exibição — a planilha preenche ora um, ora outro (e às vezes só o de exibição,
    como no Sítio dos Nogueiras). None quando a usina não tem a linha UFV preenchida."""
    if not nome:
        return None
    k = _nrm(nome)
    if POWER_UFV.get(k):
        return POWER_UFV[k]
    d = USINA_DISPLAY.get(str(nome).strip())                 # supervisório → exibição
    if d and POWER_UFV.get(_nrm(d)):
        return POWER_UFV[_nrm(d)]
    for sup, disp in USINA_DISPLAY.items():                  # exibição → supervisório
        if _nrm(disp) == k and POWER_UFV.get(_nrm(sup)):
            return POWER_UFV[_nrm(sup)]
    return None


# ── BD_Trackers (aba do BD_Performance): relação tracker ↔ inversor (começou no Thopen) ──
BD_TRK_INV    = {}   # {nrm(usina_sup): {tracker_num(int): inversor_sup}}
INV_TRK       = {}   # {nrm(usina_sup): {nrm(inversor_sup): [tracker_nums]}}
BD_TRK_USINAS = set()  # nrm(usina_sup) cobertas pela planilha


def _findcol_exact(cols, *names):
    low = {str(c).strip().lower(): c for c in cols}
    for n in names:
        if n.lower() in low:
            return low[n.lower()]
    return None


def _nome_base(s):
    """Nome 'base' p/ casar usinas entre fontes que usam ids diferentes: remove '(id)' do INÍCIO
    (PG: '(289) Nome') e do FIM (BD/API PV: 'Nome (73)') e normaliza."""
    s = str(s or "")
    s = re.sub(r"^\s*\(\d+\)\s*", "", s)
    s = re.sub(r"\s*\(\d+\)\s*$", "", s)
    return _nrm(s.strip())


def load_bd_trackers():
    """Carrega a aba 'BD_Trackers' (tracker↔inversor por usina). Chaveado por NOME-BASE (sem id)
    p/ casar com o PG; inversor pela coluna 'Inversor' (display, ex.: 'Inversor 1.1' = device_name
    do PG). Tolerante a usina FORA da planilha (R-10 degrada, não quebra)."""
    global BD_TRK_INV, INV_TRK, BD_TRK_USINAS
    try:
        df = pd.read_excel(_bd_readable_path(), sheet_name="BD_Trackers", header=2)
    except Exception as e:
        print(f"[AVISO] BD_Trackers não carregado: {e}")
        return
    c_us  = _findcol_exact(df.columns, "Usina Supervisório", "Usina Supervisorio")
    c_ivd = _findcol_exact(df.columns, "Inversor")                      # display (= device_name PG)
    c_ivs = _findcol_exact(df.columns, "Inversor Supervisório", "Inversor Supervisorio")
    c_trk = _findcol_exact(df.columns, "Tracker")
    if not (c_us and c_trk and (c_ivd or c_ivs)):
        print(f"[AVISO] BD_Trackers sem as colunas esperadas — achei {list(df.columns)[:9]}")
        return
    bd, inv_trk, usinas = {}, {}, set()
    for _, row in df.iterrows():
        us, tk = row[c_us], row[c_trk]
        iv = row[c_ivd] if (c_ivd and pd.notna(row[c_ivd])) else (row[c_ivs] if c_ivs else None)
        if pd.isna(us) or iv is None or pd.isna(iv) or pd.isna(tk):
            continue
        usn, ivs = _nome_base(us), str(iv).strip()
        try:
            tkn = int(float(tk))
        except (TypeError, ValueError):
            continue
        bd.setdefault(usn, {})[tkn] = ivs
        inv_trk.setdefault(usn, {}).setdefault(_nrm(ivs), []).append(tkn)
        usinas.add(usn)
    BD_TRK_INV, INV_TRK, BD_TRK_USINAS = bd, inv_trk, usinas
    print(f"[OK] BD_Trackers: {len(usinas)} usinas | "
          f"{sum(len(v) for v in bd.values())} trackers mapeados a inversores")


def _bd_trk_offset(bdm):
    """Offset da numeração da planilha p/ a LOCAL da fonte (TRK1..N). A aba às vezes numera o
    COMPLEXO inteiro em sequência por sub-usina (Céu Azul III = 41..60, Altair 5 = 90..113): se o
    mapa da usina-supervisório não começa em 1, o nº local n corresponde ao (n + menor - 1)."""
    if not bdm:
        return 0
    lo = min(bdm)
    return (lo - 1) if lo > 1 else 0


def _bd_trk_lookup(nome_raw, num):
    """Inversor do tracker `num` (numeração LOCAL da fonte) na usina `nome_raw` — tenta direto e
    com o offset da planilha. None se não mapeado."""
    if num is None:
        return None
    bdm = BD_TRK_INV.get(_nome_base(nome_raw)) or {}
    if num in bdm:
        return bdm[num]
    off = _bd_trk_offset(bdm)
    return bdm.get(num + off) if off else None


def _pot_inv(plant_sup: str, inv_api: str, inv_disp: str = None):
    """Potência (kWp) do inversor pelas chaves supervisório (plant['nome'], device_name)."""
    d = POWER_INV.get(plant_sup) or POWER_INV.get((plant_sup or "").strip())
    if not d:
        return None
    for k in (inv_api, inv_disp):
        if k:
            v = d.get(_nrm(k))
            if v is not None:
                return v
    return None


def maybe_reload_equipamentos():
    """Recarrega o cadastro se o BD_Performance mudou (verificação barata por mtime)."""
    try:
        m = os.path.getmtime(_bd_perf_path())
    except OSError:
        return
    if m == _bd_mtime:
        return
    with _bd_lock:
        if m == _bd_mtime:           # outro thread já recarregou
            return
        print("[BD] BD_Performance alterado -> recarregando cadastro (esperadas/nomes/Full O&M/potência)...")
        load_equipamentos()
        load_metas()
        load_usina_codigos()
        load_bd_trackers()


# ── Metas / previsto: BD_Performance, abas "Info Geral" e "Info Mensal" ───────
# Espelha as queries M do Power BI (InfoGeral / InfoMensal). São a fonte das METAS
# usadas para comparar a performance ao vivo:
#   • Info Geral  → potência da UFV, nº de inversores, P50, perdas por degradação (por usina)
#   • Info Mensal → PR Previsto 1° Ano (%) e IPOA/GHI Previsto (por usina × mês)
# Regra do Power BI: PR Previsto (%) = PR Previsto 1° Ano (%) + Perdas por degradação.
# Chave de join = nome de EXIBIÇÃO da usina (coluna "Usina", ex.: "Araputanga"),
# o mesmo que nome_usina()/USINA_DISPLAY devolvem para o lado ao vivo.
INFO_GERAL    = {}   # {usina_nrm: {usina, cliente, potencia_kwp, potencia_mwp, degradacao, qtd_inv, p50_mwh}}
PR_PREVISTO   = {}   # {usina_nrm: {(ano, mes): {pr_previsto, pr_previsto_1ano, ipoa_previsto, ghi_previsto, p50_mwh, disp_alvo}}}
_metas_mtime  = 0.0


def _unaccent(s) -> str:
    return "".join(c for c in unicodedata.normalize("NFKD", str(s)) if not unicodedata.combining(c))


def _col(cols, *needles, exclude=()):
    """Acha a 1ª coluna cujo nome (sem acento, minúsculo) contém todos os `needles`
    e nenhum dos `exclude`. Robusto a acentos/variações de cabeçalho da planilha."""
    nd = [_unaccent(n).lower() for n in needles]
    ex = [_unaccent(e).lower() for e in exclude]
    for c in cols:
        cl = _unaccent(c).lower()
        if all(n in cl for n in nd) and not any(e in cl for e in ex):
            return c
    return None


def _num(v):
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    return f if f == f else None   # descarta NaN


# Estado → região do Brasil. Chave = nome do estado NORMALIZADO (sem acento/minúsculo), então
# cobre "São Paulo"/"Sao Paulo", siglas (SP) e nomes completos. Derivado no código (não gravamos
# no BD_Performance, que é o mestre da plataforma + Power BI). Usado p/ agrupar por região no painel
# e planejar rondas de trackers por proximidade geográfica.
_UF_REGIAO = {
    "norte":        ["AC", "Acre", "AP", "Amapa", "AM", "Amazonas", "PA", "Para", "RO", "Rondonia",
                     "RR", "Roraima", "TO", "Tocantins"],
    "nordeste":     ["AL", "Alagoas", "BA", "Bahia", "CE", "Ceara", "MA", "Maranhao", "PB", "Paraiba",
                     "PE", "Pernambuco", "PI", "Piaui", "RN", "Rio Grande do Norte", "SE", "Sergipe"],
    "centro-oeste": ["DF", "Distrito Federal", "GO", "Goias", "MT", "Mato Grosso",
                     "MS", "Mato Grosso do Sul"],
    "sudeste":      ["ES", "Espirito Santo", "MG", "Minas Gerais", "RJ", "Rio de Janeiro",
                     "SP", "Sao Paulo"],
    "sul":          ["PR", "Parana", "RS", "Rio Grande do Sul", "SC", "Santa Catarina"],
}
_ESTADO2REGIAO = {_nrm(n): reg.capitalize().replace("Centro-oeste", "Centro-Oeste")
                  for reg, nomes in _UF_REGIAO.items() for n in nomes}


def _regiao_do_estado(estado):
    """Nome da região (Norte/Nordeste/Centro-Oeste/Sudeste/Sul) a partir do estado. None se não mapear."""
    if not estado:
        return None
    return _ESTADO2REGIAO.get(_nrm(str(estado).strip()))


def load_metas():
    """(Re)carrega as METAS das abas 'Info Geral' e 'Info Mensal' do BD_Performance.
    Preenche INFO_GERAL (por usina) e PR_PREVISTO (por usina × mês). Mesma fonte do
    cadastro, então é recarregada junto pelo mtime."""
    global INFO_GERAL, PR_PREVISTO, _metas_mtime
    try:
        path = _bd_perf_path()
        rd = _bd_readable_path()

        # --- Info Geral: ACHA a linha do cabeçalho, não assume a 1ª ---
        # Em 30/07 alguém inseriu linha acima do cabeçalho e a aba passou a ser lida com as 22
        # colunas como "Unnamed: N": o INFO_GERAL zerou (0 usinas) e levou junto o seletor Cliente
        # do gráfico de PR, a potência/nº de inversores e o P50 de fallback — tudo em silêncio,
        # porque o log ainda dizia "[OK]". Procurar a linha que TEM "Usina" custa uma leitura de
        # 8 linhas e torna a planilha à prova de inserção de linha no topo.
        dg = None
        for _h in range(8):
            _try = pd.read_excel(rd, sheet_name="Info Geral", header=_h)
            _cols = [str(c).strip() for c in _try.columns]
            if _col(_cols, "usina") and _col(_cols, "cliente"):
                dg = _try
                if _h:
                    print(f"[metas] Info Geral: cabeçalho na linha {_h + 1} (não na 1ª) — ajustado")
                break
        if dg is None:
            raise ValueError("aba 'Info Geral' sem cabeçalho reconhecível (nem 'Usina' nem 'Cliente' "
                             "nas 8 primeiras linhas) — confira se inseriram/removeram linhas no topo")
        dg.columns = [str(c).strip() for c in dg.columns]
        gc_us  = _col(dg.columns, "usina")
        gc_kwp = _col(dg.columns, "potencia", "kwp")
        gc_mwp = _col(dg.columns, "potencia", "mwp")
        gc_deg = _col(dg.columns, "degrada")
        gc_inv = _col(dg.columns, "quantidade", "inversor")
        gc_p50 = _col(dg.columns, "p50")
        gc_cli = _col(dg.columns, "cliente")
        gc_est = _col(dg.columns, "estado")
        gc_reg = _col(dg.columns, "regi")     # coluna "Região" da Info Geral (Levi 03/07): fonte
        info = {}                             # OFICIAL p/ ronda/agrupamentos; UF→região é só fallback
        for _, r in dg.iterrows():
            if not gc_us or pd.isna(r[gc_us]):
                continue
            u = str(r[gc_us]).strip()
            if not u:
                continue
            estado = str(r[gc_est]).strip() if gc_est and pd.notna(r[gc_est]) else None
            regiao = str(r[gc_reg]).strip() if gc_reg and pd.notna(r[gc_reg]) else ""
            info[_nrm(u)] = {
                "usina":        u,
                "cliente":      str(r[gc_cli]).strip() if gc_cli and pd.notna(r[gc_cli]) else None,
                "estado":       estado,
                "regiao":       regiao or _regiao_do_estado(estado),
                "potencia_kwp": _num(r[gc_kwp]) if gc_kwp else None,
                "potencia_mwp": _num(r[gc_mwp]) if gc_mwp else None,
                "degradacao":   (_num(r[gc_deg]) or 0.0) if gc_deg else 0.0,
                "qtd_inv":      _num(r[gc_inv]) if gc_inv else None,
                "p50_mwh":      _num(r[gc_p50]) if gc_p50 else None,
            }

        # --- Info Mensal (cabeçalho na 2ª linha; 1ª coluna é índice em branco) ---
        dm = pd.read_excel(rd, sheet_name="Info Mensal", header=1)
        dm.columns = [str(c).strip() for c in dm.columns]
        mc_us   = _col(dm.columns, "usina")
        mc_mes  = _col(dm.columns, "mes", exclude=("comenta",))
        mc_pr   = _col(dm.columns, "pr previsto")
        mc_ipoa = _col(dm.columns, "ipoa", "previsto")
        mc_ghi  = _col(dm.columns, "ghi", "previsto")
        mc_p50  = _col(dm.columns, "p50")
        mc_disp = _col(dm.columns, "disponibilidade")
        prev = {}
        for _, r in dm.iterrows():
            if not mc_us or pd.isna(r[mc_us]) or not mc_mes or pd.isna(r[mc_mes]):
                continue
            u = str(r[mc_us]).strip()
            ts = pd.to_datetime(r[mc_mes], errors="coerce", dayfirst=True)
            if pd.isna(ts):
                continue
            deg = info.get(_nrm(u), {}).get("degradacao", 0.0) or 0.0
            pr1 = _num(r[mc_pr]) if mc_pr else None
            prev.setdefault(_nrm(u), {})[(ts.year, ts.month)] = {
                "pr_previsto":      (pr1 + deg) if pr1 is not None else None,   # = regra do Power BI
                "pr_previsto_1ano": pr1,
                "ipoa_previsto":    _num(r[mc_ipoa]) if mc_ipoa else None,
                "ghi_previsto":     _num(r[mc_ghi]) if mc_ghi else None,
                "p50_mwh":          _num(r[mc_p50]) if mc_p50 else None,
                "disp_alvo":        _num(r[mc_disp]) if mc_disp else None,
            }

        INFO_GERAL, PR_PREVISTO = info, prev
        # mesmo guard do load_equipamentos: metas vazias não carimbam o mtime (reboot 26/08)
        if not info:
            print("[FALHA] BD_Performance/Info Geral veio VAZIO — não carimbo o mtime; "
                  "o próximo ciclo tenta de novo.")
            return
        try:
            _metas_mtime = os.path.getmtime(path)
        except OSError:
            _metas_mtime = 0.0
        # "[OK] ... 0 usinas" era a pior parte: lia-se como sucesso. Cadastro vazio é FALHA.
        if not info:
            print("[FALHA] BD_Performance/Info Geral: 0 usinas no cadastro — cliente, potência, "
                  "nº de inversores e P50 de fallback ficam INDISPONÍVEIS. Confira a aba.")
        print(f"[OK] BD_Performance/Info Geral+Mensal: {len(info)} usinas | "
              f"{sum(len(v) for v in prev.values())} linhas mensais de meta")
    except Exception as e:
        print(f"[AVISO] BD_Performance (Info Geral/Mensal) não carregado: {e}")


# ── Meta de geração das usinas do BANCO (Thopen): BD_Thopen.xlsx, tabela Historico_2026 ──
# O P50/meta das usinas do banco NÃO está no BD_Performance (o Info Mensal cobre outras carteiras);
# mora aqui — MESMA fonte do dashboard_thopen. {nrm(usina): {mes_int: {meta_mwh, ipoa_meta, pr_meta}}}.
THOPEN_META = {}
_BD_THOPEN_CANDS = [
    os.environ.get("BD_THOPEN_PATH"),
    # (caminhos do OneDrive removidos em 25/08 — 100% API; ver o comentário do _BD_PERF_ONLINE_CANDS)
]


def _bd_thopen_path():
    for p in _BD_THOPEN_CANDS:
        if p and os.path.exists(p):
            return p
    return _base_espelho("BD_Thopen.xlsx")      # servidor sem OneDrive: espelho por push


def load_thopen_meta():
    """Lê a tabela nomeada Historico_2026 (meta kWh / irradiância-meta / PR por usina×mês)."""
    global THOPEN_META
    path = _bd_thopen_path()
    if not path:
        print("[AVISO] BD_Thopen.xlsx não encontrado — meta gerencial do banco ficará vazia")
        return
    try:
        import openpyxl
        wb = openpyxl.load_workbook(path, data_only=True)
        # ESCOLHE A TABELA PELAS COLUNAS, NÃO SÓ PELO NOME. O BD_Thopen tem DUAS tabelas que
        # começam com "Historico" e elas NÃO são intercambiáveis:
        #   Historico_2026 -> Usina | Ano | Mês | FC | Meta | Meta Irradiação | PR   (formato LARGO)
        #   Historico      -> Usina | Ano | Mês | Tipo | Valor                        (formato LONGO, 2023-2026)
        # Só a primeira serve aqui. Casar por prefixo pegaria a segunda quando a do ano faltasse, e
        # o `ci()` abaixo (que procura por substring) não acharia "meta"/"irradia"/"pr" nenhuma:
        # o gerencial ficaria com meta VAZIA para todas as usinas, sem erro na tela. Por isso a
        # candidata só é aceita se tiver as três colunas que este leitor precisa. O nome com o ano
        # tem preferência; o resto é desempate.
        sheet = ref = tabela = None
        _pref = f"Historico_{datetime.now().year}"
        _cands = [(n, ws, ws.tables[n].ref) for ws in wb.worksheets for n in list(ws.tables)
                  if str(n).strip().lower().startswith("historico")]
        _cands.sort(key=lambda c: (c[0] != _pref, str(c[0])))
        # ESPELHO DA API (migração 25/08): o arquivo pode não ter NENHUMA tabela nomeada — a API
        # não as expõe. Nesse caso as candidatas viram as próprias ABAS, com a linha de cabeçalho
        # detectada (o BD_Thopen tem abas com título na linha 1 e cabeçalho na 2, e abas que
        # começam na coluna B). A validação por colunas logo abaixo continua sendo quem decide —
        # é ela que separa o formato LARGO (Meta/Irradiação/PR) do LONGO (Tipo/Valor).
        if not _cands:
            from openpyxl.utils import get_column_letter as _gcl
            _ano = str(datetime.now().year)
            _abas = []
            for _ws in wb.worksheets:
                for _r in range(1, min(4, _ws.max_row) + 1):
                    _vals = [str(c.value).strip().lower() if c.value is not None else "" for c in _ws[_r]]
                    if any(v in ("usina", "data") for v in _vals):
                        _c1 = next((i + 1 for i, v in enumerate(_vals) if v), 1)
                        _abas.append((_ws.title, _ws,
                                      f"{_gcl(_c1)}{_r}:{_gcl(_ws.max_column)}{_ws.max_row}"))
                        break
            _abas.sort(key=lambda c: (_ano not in c[0], str(c[0])))   # a aba com o ano na frente
            _cands = _abas
        for _n, _ws, _rf in _cands:
            _hd = [str(c.value).strip().lower() if c.value is not None else "" for c in list(_ws[_rf])[0]]
            if (any("meta" in h for h in _hd) and any("irradia" in h for h in _hd)
                    and any(h == "pr" or h.startswith("pr") for h in _hd)):
                sheet, ref, tabela = _ws, _rf, _n
                break
        if not ref:
            wb.close()
            print("[AVISO] nenhuma tabela Historico* com Meta/Irradiação/PR no BD_Thopen — "
                  "meta gerencial ficará vazia")
            return
        cells = list(sheet[ref])
        hdr = [str(c.value).strip().lower() if c.value is not None else "" for c in cells[0]]

        def ci(*needles):
            for i, h in enumerate(hdr):
                if any(n in h for n in needles):
                    return i
            return None
        iU, iMes, iMeta, iIrr, iPR = ci("usina"), ci("mês", "mes"), ci("meta"), ci("irradia"), ci("pr")
        out = {}
        for row in cells[1:]:
            v = [c.value for c in row]
            u = v[iU] if iU is not None else None
            if not u:
                continue
            mv = v[iMes] if iMes is not None else None
            m = mv.month if hasattr(mv, "month") else (int(mv) if isinstance(mv, (int, float)) else None)
            if not m:
                continue
            meta = v[iMeta] if (iMeta is not None and isinstance(v[iMeta], (int, float))) else None
            meta_mwh = (meta / 1000.0 if (meta and meta > 10000) else meta)   # auto kWh→MWh
            out.setdefault(_nrm(str(u).strip()), {})[int(m)] = {
                "meta_mwh": meta_mwh,
                "ipoa_meta": float(v[iIrr]) if (iIrr is not None and isinstance(v[iIrr], (int, float))) else None,
                "pr_meta": float(v[iPR]) if (iPR is not None and isinstance(v[iPR], (int, float))) else None,
            }
        wb.close()
        THOPEN_META = out
        print(f"[OK] BD_Thopen/{tabela} (aba {sheet.title}): {len(out)} usinas com meta (gerencial)")
    except Exception as e:
        print(f"[AVISO] BD_Thopen meta não carregado: {e}")


def info_geral(usina_display):
    """Metadados da UFV (potência, P50, degradação) pelo nome de exibição. None se ausente."""
    return INFO_GERAL.get(_nrm(usina_display)) if usina_display else None


def pr_previsto(usina_display, ano=None, mes=None):
    """PR Previsto (fração, já com degradação) da usina no mês. Sem ano/mês usa o mês atual.
    Faz fallback para o mesmo mês de outro ano, ou a meta mais recente, se faltar o exato."""
    d = PR_PREVISTO.get(_nrm(usina_display)) if usina_display else None
    if not d:
        return None
    if ano is None or mes is None:
        hoje = datetime.now()
        ano, mes = hoje.year, hoje.month
    rec = d.get((ano, mes))
    if rec is None:
        mesmo_mes = [v for (y, m), v in d.items() if m == mes]
        rec = mesmo_mes[-1] if mesmo_mes else d[max(d)]
    return rec



def meta_geracao_dia(usina_display, data, ipoa, validacao):
    """Meta de geração do DIA (MWh) — espelha fielmente a coluna DAX 'Meta Mensal Geração':
        1. Validação == 0          -> P50 mensal / dias do mês
        2. IPOA > 0 (e validado)   -> IPOA × PR Meta × Potência (MWp)
        3. senão (IPOA <= 0/nulo)  -> P50 mensal / dias do mês
    `data` = date/datetime da linha; `ipoa` em kWh/m²; `validacao` numérico (0 = não validado).
    P50 mensal e PR Meta vêm da Info Mensal; potência da Info Geral. None se faltar insumo."""
    if data is None:
        return None
    ano, mes = data.year, data.month
    rec = pr_previsto(usina_display, ano, mes)
    g = info_geral(usina_display)
    dias_no_mes = calendar.monthrange(ano, mes)[1]
    p50 = rec.get("p50_mwh") if rec else None
    fallback = (p50 / dias_no_mes) if (p50 is not None and dias_no_mes) else None

    val = _num(validacao)
    if val == 0:                                   # 1. dia não validado
        return fallback
    pr  = rec.get("pr_previsto") if rec else None
    pot = g.get("potencia_mwp") if g else None
    if ipoa is not None and ipoa > 0 and pr is not None and pot is not None:
        return ipoa * pr * pot                     # 2. ramo IPOA
    return fallback                                # 3. IPOA <= 0 ou nulo


load_equipamentos()   # carga inicial do cadastro mestre
load_metas()          # carga inicial das metas (Info Geral / Info Mensal)
load_thopen_meta()    # meta de geração do BANCO/Thopen (BD_Thopen / Historico_2026)
load_bd_trackers()    # carga inicial da relação tracker↔inversor (aba BD_Trackers)


@app.before_request
def _auto_reload_bd():
    """Qualquer refresh forçado (force=1, o que o botão Atualizar faz) relê o BD_Performance se mudou.
    Robusto independente da versão do frontend em cache no navegador."""
    if flask_request.args.get("force") == "1":
        maybe_reload_equipamentos()
        maybe_reload_tickets()


def maybe_reload_tickets():
    """Recarrega a planilha de Tickets se ela mudou (mtime). Com LOCK: o botão Atualizar
    dispara vários force=1 em paralelo e ler o xlsx em várias threads ao mesmo tempo
    (pandas/openpyxl) pode derrubar o processo."""
    path = _tickets_path()
    if not path:
        return
    try:
        m = os.path.getmtime(path)
    except OSError:
        return
    if m == _tickets_mtime:
        return
    with _tickets_lock:
        if m == _tickets_mtime:        # outra thread já recarregou
            return
        print("[Tickets] planilha alterada -> recarregando ocorrências...")
        load_tickets_trackers()
        load_tickets_os()


def nome_usina(plant_id, nome_api):
    # Nome de exibição vem do BD_Performance (coluna "Usina"); senão, o nome da própria API
    return USINA_DISPLAY.get(nome_api.strip()) or nome_api.strip()


# ── Auth & helpers ─────────────────────────────────────────────────────────────
# Token da API PV CACHEADO: antes, autenticava a CADA chamada (cada /api/data, cada
# detalhe, cada prewarm) — o que fazia a API PV limitar/bloquear o /authenticate e
# devolver resposta não-JSON (500). Agora autentica 1× e reusa pela validade do JWT.
_pv_token      = {"token": "", "exp": 0.0}
_pv_token_lock = threading.Lock()


def get_token(force=False) -> str:
    now = time.time()
    if not force and _pv_token["token"] and now < _pv_token["exp"]:
        return _pv_token["token"]
    with _pv_token_lock:
        if not force and _pv_token["token"] and time.time() < _pv_token["exp"]:
            return _pv_token["token"]
        r = _http().post(f"{BASE_URL}/authenticate",
                          json={"username": USERNAME, "password": PASSWORD}, timeout=30)
        try:
            tok = r.json()["token"]
        except Exception:
            if _pv_token["token"]:                 # resposta inválida → reusa o anterior
                return _pv_token["token"]
            raise RuntimeError(f"API PV /authenticate falhou (HTTP {r.status_code})")
        exp = time.time() + 2700                   # fallback 45 min
        try:
            import base64
            pl = tok.split(".")[1]; pl += "=" * (-len(pl) % 4)
            jexp = json.loads(base64.urlsafe_b64decode(pl)).get("exp")
            if jexp:
                exp = float(jexp) - 60             # 1 min de folga antes do vencimento
        except Exception:
            pass
        _pv_token.update({"token": tok, "exp": exp})
        return tok


_plants_cache = {"ts": 0.0, "data": None}   # lista de usinas (id/nome) — muda raramente
_plants_lock  = threading.Lock()

# ── 2ª conta da API PV: OEM (SEMP) ───────────────────────────────────────────
# A conta principal NÃO enxerga a UFV Tucano; a conta oem@ enxerga (e mais 145 iguais).
# Não dá p/ simplesmente trocar a credencial: medido em 31/07, a conta OEM recebe
# {"message":"Invalid permission"} no /plant_devices — de onde saem os NOMES dos inversores e a
# lista de quem existe quando a usina não teve leitura no dia. Trocar tudo por ela apagaria o
# nome de inversor das 145 usinas atuais. Então as duas convivem: cada usina é buscada com o
# token da conta que a enxerga. Se a Solan liberar plant_devices p/ a OEM, dá p/ unificar.
PV_OEM_USERNAME = os.environ.get("PV_OEM_USERNAME", "")
PV_OEM_PASSWORD = os.environ.get("PV_OEM_PASSWORD", "")
# As usinas que só a conta OEM enxerga, agrupadas pela ABA (cliente) a que pertencem. Era um
# conjunto único e um booleano `somente_oem`, o que só permitia DUAS abas: a principal e "a outra".
# Quando o Alves Lima entrou (19/08, MORADA NOVA), ele viria pela mesma credencial da SEMP e cairia
# na aba da SEMP — cliente errado no rótulo. Com o mapa, cada cliente é uma linha e o resto do
# motor não muda. Tupi Paulista fica FORA de propósito: já vem da 2C.
PV_FONTES = {
    "semp":      {18758732},    # UFV Tucano
    "alveslima": {18766373},    # MORADA NOVA (CE) — 8 inversores, 2.508 kWp, ativa desde 05/08/2026
}
PV_OEM_PLANTS   = set().union(*PV_FONTES.values()) if PV_FONTES else set()
_pv_oem_token   = {"token": None, "exp": 0.0}
_pv_oem_lock    = threading.Lock()


def get_token_oem(force=False) -> str:
    """Token da conta OEM — mesmo login programático da principal, outra credencial."""
    if not (PV_OEM_USERNAME and PV_OEM_PASSWORD):
        return ""
    now = time.time()
    if not force and _pv_oem_token["token"] and now < _pv_oem_token["exp"]:
        return _pv_oem_token["token"]
    with _pv_oem_lock:
        if not force and _pv_oem_token["token"] and time.time() < _pv_oem_token["exp"]:
            return _pv_oem_token["token"]
        try:
            r = _http().post(f"{BASE_URL}/authenticate",
                              json={"username": PV_OEM_USERNAME, "password": PV_OEM_PASSWORD},
                              timeout=30)
            tok = r.json()["token"]
        except Exception as e:
            if _pv_oem_token["token"]:
                return _pv_oem_token["token"]
            print(f"[API PV/OEM] authenticate falhou: {e}")
            return ""
        exp = time.time() + 2700
        try:
            import base64
            pl = tok.split(".")[1]; pl += "=" * (-len(pl) % 4)
            jexp = json.loads(base64.urlsafe_b64decode(pl)).get("exp")
            if jexp:
                exp = float(jexp) - 60
        except Exception:
            pass
        _pv_oem_token.update({"token": tok, "exp": exp})
        return tok


def _pv_is_oem(plant_id) -> bool:
    try:
        return int(plant_id) in PV_OEM_PLANTS
    except (TypeError, ValueError):
        return False


def _pv_fonte_de(plant_id):
    """Aba a que esta usina pertence. None = a principal (Thopen). Substitui o antigo teste
    booleano `_pv_is_oem(id) == somente_oem`, que não sabia distinguir dois clientes servidos
    pela MESMA credencial OEM."""
    try:
        pid = int(plant_id)
    except (TypeError, ValueError):
        return None
    for fonte, ids in PV_FONTES.items():
        if pid in ids:
            return fonte
    return None


def _pv_token_for(plant_id) -> str:
    """Token da conta que ENXERGA esta usina. É o que permite as ~25 chamadas de
    `get_plants(get_token())` espalhadas pelo app continuarem valendo sem alteração."""
    if _pv_is_oem(plant_id):
        return get_token_oem() or get_token()
    return get_token()


def get_plants(token: str, force=False) -> list:
    """Lista de usinas da API PV, cacheada por CACHE_TTL. A relação de usinas muda
    raramente, mas vários endpoints a consultam UMA VEZ POR USINA (a aba Curva das
    strings rebaixava /plants ~108×, uma por usina, a cada abertura). O dado DENTRO de
    cada usina segue buscado fresco nos outros endpoints — aqui só evitamos repetir o
    download da lista inteira."""
    now = time.time()
    if not force and _plants_cache["data"] is not None and (now - _plants_cache["ts"]) < CACHE_TTL:
        return _plants_cache["data"]
    with _plants_lock:
        if not force and _plants_cache["data"] is not None and (time.time() - _plants_cache["ts"]) < CACHE_TTL:
            return _plants_cache["data"]
        r = _http().get(f"{BASE_URL}/plants", headers={"x-access-token": token}, timeout=30)
        data = r.json()
        if isinstance(data, list) and data:        # só cacheia resposta válida e não vazia
            # Junta as usinas que SÓ a conta OEM enxerga (UFV Tucano). Entram na mesma lista,
            # com o mesmo formato, para todo o resto do app (overview, drill, curva, ronda)
            # continuar funcionando sem saber que existe uma 2ª conta.
            if PV_OEM_USERNAME:
                try:
                    _ids = {p.get("id") for p in data}
                    _t2 = get_token_oem()
                    if _t2:
                        _o = _http().get(f"{BASE_URL}/plants",
                                          headers={"x-access-token": _t2}, timeout=30).json()
                        extra = [p for p in (_o if isinstance(_o, list) else [])
                                 if p.get("id") in PV_OEM_PLANTS and p.get("id") not in _ids]
                        if extra:
                            data = data + extra
                            print(f"[API PV/OEM] +{len(extra)} usina(s) da conta OEM: "
                                  f"{[p.get('nome') or p.get('name') for p in extra]}")
                except Exception as e:
                    print(f"[API PV/OEM] não consegui juntar as usinas da conta OEM: {e}")
            _plants_cache["data"], _plants_cache["ts"] = data, time.time()
        return data


def parse_cj(raw) -> dict:
    if isinstance(raw, str):
        try:
            return json.loads(raw)
        except Exception:
            return {}
    return raw or {}


# ── API PV: string ativa = relativa à média do inversor ───────────────────────
def _na_janela_sol(agora=None) -> bool:
    """True se 'agora' está na janela de sol confiável (09:00–15:00 local)."""
    h = (agora or datetime.now()).hour
    return STRING_JANELA_INI <= h < STRING_JANELA_FIM


def _ipv_ativas(correntes: list, em_janela=None) -> list:
    """Recebe as correntes (A) das strings de UM inversor → lista de bools 'ativa'.
    DENTRO de 09:00–15:00 (sol forte): ativa se corrente > STRING_JANELA_MIN_A (1 A) — régua
    simples, sem falso negativo porque a irradiância é alta.
    FORA da janela (início/fim de dia, noite): ativa se corrente > STRING_JANELA_MIN_A (1 A)
    — passou de 1 A, tem corrente real = ativa — OU (para strings abaixo de 1 A) se
    >= STRING_ATIVA_FRAC × média(strings produzindo), pegando produtoras em luz fraca.
    Valor 0 = sempre inativa."""
    if em_janela is None:
        em_janela = _na_janela_sol()
    if em_janela:
        return [isinstance(c, (int, float)) and c > STRING_JANELA_MIN_A for c in correntes]
    produzindo = [c for c in correntes if isinstance(c, (int, float)) and c > 0]
    if not produzindo:
        return [False] * len(correntes)
    limiar = (sum(produzindo) / len(produzindo)) * STRING_ATIVA_FRAC
    # > 1 A já conta como ativa (tem corrente); abaixo disso, usa a régua relativa
    return [isinstance(c, (int, float)) and c > 0 and (c > STRING_JANELA_MIN_A or c >= limiar)
            for c in correntes]


def _str_key(plant_id, inv_id, ipv) -> str:
    return f"{plant_id}|{inv_id}|{ipv}"


def _classifica_strings(plant_id, inv_id, ipv_keys, correntes):
    """Classifica as strings de UM inversor (instantâneo, relativo à mediana do PRÓPRIO
    inversor). → lista de status alinhada a ipv_keys, em {trancada, sem_corrente,
    baixa_perf, ativa, inativa}.
      • trancada   = marcada à mão (MPPT sem string) → fora da contagem de ativas
      • inativa    = inversor parado (mediana ~0: noite/nublado) → NÃO é falha
      • sem_corrente = string morta (=0) com o inversor produzindo → falha tipo 1
      • baixa_perf = corrente < 60% da mediana das demais → falha tipo 2
      • ativa      = produzindo normal
    'ativas' = ativa + baixa_perf (produzindo, descontadas as trancadas)."""
    trancada = [_str_key(plant_id, inv_id, k) in _trancadas for k in ipv_keys]
    prod = sorted(c for c, t in zip(correntes, trancada)
                  if (not t) and isinstance(c, (int, float)) and c > STRING_SEM_CORRENTE_A)
    med  = prod[len(prod) // 2] if prod else 0.0
    produzindo = med >= STRING_INV_MIN_MED_A
    out = []
    for c, t in zip(correntes, trancada):
        cv = c if isinstance(c, (int, float)) else 0.0
        if t:
            out.append("trancada")
        elif not produzindo:
            out.append("inativa")
        elif cv <= STRING_SEM_CORRENTE_A:
            out.append("sem_corrente")
        elif cv < STRING_BAIXA_PERF_FRAC * med:
            out.append("baixa_perf")
        else:
            out.append("ativa")
    return out


def _str_ativas(statuses) -> int:
    return sum(1 for s in statuses if s in ("ativa", "baixa_perf"))


# ── Monta resumo de usina a partir dos registros brutos ───────────────────────
def build_summary(plant: dict, records: list) -> dict:
    pid  = plant["id"]
    nome = nome_usina(pid, plant["nome"])

    # by_inv = TODOS os registros do dia por inversor (precisa p/ o fallback "último com Ipv")
    by_inv, latest = {}, {}
    for rec in records:
        inv_id = rec.get("idefinversor")
        by_inv.setdefault(inv_id, []).append(rec)
        ts = rec.get("tsleitura_new", "")
        if inv_id not in latest or ts > latest[inv_id].get("tsleitura_new", ""):
            latest[inv_id] = rec

    ts_max = max((r.get("tsleitura_new", "") for r in latest.values()), default="")

    falha = False
    if ts_max:
        try:
            diff = (datetime.now() - datetime.strptime(ts_max, "%Y-%m-%d %H:%M:%S")).total_seconds() / 60
            falha = diff > COMM_ALERT_MINUTES
        except Exception:
            pass

    strings_ativas = 0
    temps = []
    pacs, ativas_inv = [], []                 # potência ativa (Pac) + strings ativas POR inversor
    sb = plant["nome"].strip() in STRING_BOX
    sem_visao = 0                             # inversores String Box SEM combiner exposta na Plataforma
    em_rampa  = 0                             # inversores com corrente REAL, baixa demais p/ classificar
    neutros_ids = []                          # ids dos neutros (sem_visao/rampa) → desconto EXATO do esperado
    for inv_id, rec in latest.items():
        cj = parse_cj(rec.get("conteudojson"))
        ipv_keys  = [k for k in cj if k.startswith("Ipv") and isinstance(cj[k], (int, float))]
        _pac = cj.get("Pac")
        # Mesma régua do drill (api_plant_detail): se o ÚLTIMO ping não tem Ipv (vem só Eday/Temp),
        # busca o último do dia que TEM — evita o inversor virar "0 strings ativas" na linha-pai
        # enquanto está produzindo (descoberto na Indaiatuba 1: linha-pai 29, soma do drill 157).
        if not ipv_keys:
            for prev in sorted(by_inv.get(inv_id, []),
                               key=lambda r: r.get("tsleitura_new", ""), reverse=True):
                pcj = parse_cj(prev.get("conteudojson"))
                pk  = [k for k in pcj if k.startswith("Ipv") and isinstance(pcj[k], (int, float))]
                if pk:
                    cj, ipv_keys = pcj, pk
                    break
        _ipv_reais = sum(1 for k in ipv_keys if isinstance(cj.get(k), (int, float)) and cj[k] > STRING_SEM_CORRENTE_A)
        # Inversor GERANDO (Pac real) e sem corrente por string no day_inverter é a assinatura do
        # String Box, esteja ou não marcado no cadastro — e o drill (_pv_plant_inversores) já consulta
        # a combiner SEM olhar a planilha. A linha-pai olhava, então usina com a coluna "String Box"
        # vazia zerava: Sarandi 1/2 e Sto Antônio da Platina 1/2 (05/08) exibiam 0 ativas e -180 de
        # déficit enquanto o drill lia 136, 153 e 171 strings com corrente real vinda da combiner.
        # O gate por Pac é o que segura o custo: à noite Pac~0 e nenhuma usina nova bate na combiner
        # (medido 05/08: 8 candidatas, 71 inversores no pico — as MESMAS que o drill já pede).
        _gera = isinstance(_pac, (int, float)) and _pac >= MACRO_POT_INV_MIN
        eh_combiner = False
        if _ipv_reais <= 1 and (sb or _gera):
            # String Box: corrente por string REAL vem da COMBINER (Plataforma). O day_inverter às vezes
            # traz 24 Ipv quase todas ZERO → contar CHAVES deixava a combiner de fora (Ceilândia II
            # 23/07: 12 inv × 1 string = déficit falso -156). Conta corrente REAL.
            cmb = _plat_combiner_strings(inv_id)
            if cmb:
                cj = dict(cj); cj.update(dict(cmb["strings"]))
                ipv_keys = [k for k, _ in cmb["strings"]]
                eh_combiner = True
            elif sb:
                # Sem combiner exposta → "sem visão": não conta a string fantasma nem o esperado desse
                # inversor. Vale só para quem o CADASTRO diz ser String Box — usina de fora que também
                # não tem combiner (Pharma III/IV) fica exatamente como estava, sem contagem inventada.
                sem_visao += 1
                neutros_ids.append(inv_id)
                ipv_keys = []
        correntes = [cj[k] for k in ipv_keys]
        # exclui trancadas e aplica a régua relativa à mediana do inversor
        _at = _str_ativas(_classifica_strings(pid, inv_id, ipv_keys, correntes))
        # Inversor GERANDO com 0 strings ativas — mesma divisão do drill (ver _pv_plant_inversores):
        #   correntes ZERADAS = telemetria furada (Levi 13/07: 3.4 Altair 3) → sem visão;
        #   correntes REAIS porém baixas = RAMPA de início/fim de dia → a usina NÃO está "sem geração",
        #   está com pouca irradiância. Os dois casos saem do esperado (nada de déficit falso), mas só
        #   o segundo vira o status "Baixa irradiância" em vez de "Sem geração".
        if (sb or eh_combiner) and _at == 0 and ipv_keys and _gera:
            if any(isinstance(c, (int, float)) and c > STRING_SEM_CORRENTE_A for c in correntes):
                em_rampa += 1
            else:
                sem_visao += 1
            neutros_ids.append(inv_id)
        strings_ativas += _at
        ativas_inv.append(_at)
        pacs.append(_pac if isinstance(_pac, (int, float)) else None)
        t = cj.get("Temp")
        if isinstance(t, (int, float)):
            temps.append(t)

    esp       = ESPERADO.get(plant["nome"].strip(), {})
    inv_esp   = esp.get("inv_esp")
    str_esp   = esp.get("str_esp")
    if (sem_visao + em_rampa) and isinstance(str_esp, (int, float)) and latest:
        # Desconta as esperadas dos inversores sem visão E dos em rampa — não há contagem confiável
        # de ativas neles, cobrar o esperado geraria déficit falso. O desconto é EXATO por inversor
        # quando dá para resolver o nome (plant_devices, cacheado): o proporcional pela média criava
        # resto sempre que o neutro não era exatamente a média — Tanabi 1 (07/08): 1.6+1.7 têm 26
        # esperadas no cadastro, a média descontava 24,2, e a usina cravava "-2" com TODOS os
        # inversores em dif 0 na tela. Sem nome resolvido (falha/conta OEM), cai na média de antes.
        # (reusa o _pv_dev_names(pid, token) que JÁ EXISTIA lá no bloco das curvas — cache 30 min;
        #  a 1ª versão deste fix criou um homônimo e a def posterior o engoliu: TypeError em TODAS
        #  as usinas e o /api/data ficou preso no stale das 10:39 até o repro apontar a colisão)
        _esp_inv = ESPERADO_INV.get(plant["nome"].strip()) or {}
        _dn = _pv_dev_names(pid, _pv_token_for(pid)) if (_esp_inv and neutros_ids) else {}
        _media = str_esp / len(latest)
        _desc = sum(_esp_inv.get(_dn.get(i), _media) if _dn else _media for i in neutros_ids)
        str_esp = max(0, round(str_esp - _desc))
    diferenca = (strings_ativas - str_esp) if (str_esp is not None) else None
    # potência ativa → parada por inversor; deficit operante = tira os inversores parados.
    # (sem nome de inversor aqui p/ o esperado individual → estima pela média str_esp/qtd)
    prod, pot_med, n_off = _macro_prod(pacs)
    dif_operante = diferenca
    if (isinstance(diferenca, (int, float)) and n_off and str_esp and latest):
        esp_por_inv = str_esp / len(latest)
        dif_operante = min(0, round(diferenca + n_off * esp_por_inv))   # adiciona de volta o deficit dos parados

    return {
        "usina": nome, "plant_id": pid,
        "qtd_inversores": len(latest),
        "strings_ativas": strings_ativas,
        "pot_med": pot_med, "inv_off": n_off, "diferenca_operante": dif_operante,
        "inv_esp": inv_esp, "str_esp": str_esp, "diferenca": diferenca,
        "temp_media": round(sum(temps) / len(temps), 1) if temps else None,
        "ultima_leitura": ts_max or None,
        "sem_dados": False,
        "falha_comunicacao": falha,
        "stringbox": plant["nome"].strip() in STRING_BOX,
        # usina inteira em rampa (corrente real, baixa) → o front mostra "Baixa irradiância" no lugar
        # de "Sem geração" e neutraliza ativas/esperadas, em vez de exibir 0/0 (usina "invisível")
        "rampa": bool(em_rampa and strings_ativas == 0),
        # String Box PRODUZINDO (Pac>0) mas sem visão de string — combiner não exposta na Plataforma p/
        # os inversores (ex.: Céu Azul, Ouro Branco 23/07). NÃO é "Sem geração" (a usina gera): o front
        # mostra "Sem visão de strings" (neutro). Sem isto, ativas=0 caía em "Sem geração" falso.
        "sem_visao": bool(sem_visao and strings_ativas == 0 and not em_rampa and (pot_med or prod)),
    }


# ── Processa uma usina (visão geral) ──────────────────────────────────────────
def process_plant(token: str, plant: dict, timeout: int = 45) -> dict:
    pid  = plant["id"]
    nome = nome_usina(pid, plant["nome"])
    base = {"usina": nome, "plant_id": pid,
            "qtd_inversores": None, "strings_ativas": None,
            "temp_media": None, "ultima_leitura": None,
            "sem_dados": True, "falha_comunicacao": False,
            "stringbox": plant["nome"].strip() in STRING_BOX}
    try:
        records = _http().post(f"{BASE_URL}/day_inverter",
                                headers={"x-access-token": _pv_token_for(pid)},
                                json={"id": pid}, timeout=timeout).json()
    except Exception:
        return base
    if not records:
        return base
    return build_summary(plant, records)


# ── Severidade para ordenação ─────────────────────────────────────────────────
def severidade(r) -> int:
    # Linha histórica (substituída pelo _last_known): não é leitura de agora. A severidade dela é
    # FALHA DE COMUNICAÇÃO — sem isto, Matão 1 (0 ativas, parada desde 15/07) subia ao topo como
    # "sem geração", um diagnóstico tirado de dado de três semanas atrás.
    if r.get("dado_historico"):
        return 3
    if not r.get("sem_dados") and r.get("strings_ativas") == 0:
        return 0  # sem geração
    if not r.get("sem_dados") and r.get("diferenca") is not None and r["diferenca"] < 0:
        return 1  # falha de string
    if not r.get("sem_dados") and r.get("temp_media") is not None and r["temp_media"] >= TEMP_ALERT:
        return 2  # temp elevada
    if r.get("falha_comunicacao"):
        return 3  # falha comunicação
    if r.get("sem_dados"):
        return 4  # sem dados
    return 5      # normal


# ── Busca todos ────────────────────────────────────────────────────────────────
def fetch_all(fonte: str = None) -> list:
    token     = get_token()
    all_plants = get_plants(token)
    # Filtra apenas usinas Full O&M = Sim (se a lista estiver carregada)
    plants = [p for p in all_plants if p["nome"].strip() in FULL_OM] if FULL_OM else all_plants
    # As contas são clientes DIFERENTES na tela: a conta OEM é a SEMP, e a Tucano não pode
    # aparecer misturada com a Thopen. Cada fonte enxerga só as suas.
    plants = [p for p in plants if _pv_fonte_de(p["id"]) == fonte]
    plant_map = {p["id"]: p for p in plants}
    rows      = []

    # Concorrência moderada: um único token sob 20 requisições pesadas paralelas
    # faz a API throttlar as maiores (ex.: Saturnino, 2 MB) → vinham vazias/sem_dados.
    with ThreadPoolExecutor(max_workers=8) as ex:
        futures = {ex.submit(process_plant, token, p): p for p in plants}
        for f in as_completed(futures):
            # UMA usina explodindo não pode derrubar o payload INTEIRO: o f.result() cru propagava
            # a exceção, o _refresh_data_cache abortava e a aba Strings ficava presa no stale — foi
            # o modo de falha de 07/08 (TypeError em build_summary congelou o /api/data nas 10:39
            # SEM alarme nenhum). Usina que falhar vira linha "sem_dados" e o erro aparece no log.
            _p = futures[f]
            try:
                rows.append(f.result())
            except Exception as e:
                print(f"[fetch_all] {_p.get('nome')} ({_p.get('id')}): {type(e).__name__}: {e}")
                rows.append({"usina": nome_usina(_p["id"], _p["nome"]), "plant_id": _p["id"],
                             "qtd_inversores": None, "strings_ativas": None,
                             "temp_media": None, "ultima_leitura": None,
                             "sem_dados": True, "falha_comunicacao": False,
                             "stringbox": _p["nome"].strip() in STRING_BOX})

    rows_by_id = {r["plant_id"]: r for r in rows}

    # Passada 2 — retry paralelo leve (token renovado) para as que falharam
    sem_dados_ids = [pid for pid, r in rows_by_id.items() if r.get("sem_dados")]
    if sem_dados_ids:
        token2 = get_token()
        retry_plants = [plant_map[pid] for pid in sem_dados_ids if pid in plant_map]
        with ThreadPoolExecutor(max_workers=4) as ex:
            futures = {ex.submit(process_plant, token2, p): p for p in retry_plants}
            for f in as_completed(futures):
                try:
                    r = f.result()
                except Exception as e:
                    print(f"[fetch_all/retry] {futures[f].get('nome')}: {type(e).__name__}: {e}")
                    continue
                if not r.get("sem_dados"):
                    rows_by_id[r["plant_id"]] = r

    # Passada 3 — SEQUENCIAL (1 por vez, sem concorrência, timeout alto).
    # Resolve usinas pesadas que a API throttla sob carga paralela (ex.: Sorocaba).
    ainda_sem = [pid for pid, r in rows_by_id.items() if r.get("sem_dados")]
    if ainda_sem:
        token3 = get_token()
        for pid in ainda_sem:
            if pid not in plant_map:
                continue
            try:
                r = process_plant(token3, plant_map[pid], timeout=60)
            except Exception as e:
                print(f"[fetch_all/seq] {plant_map[pid].get('nome')}: {type(e).__name__}: {e}")
                continue
            if not r.get("sem_dados"):
                rows_by_id[pid] = r

    rows = list(rows_by_id.values())
    return sorted(rows, key=lambda x: (severidade(x), x["usina"]))


# ── Drill-down: detalhe de uma usina ──────────────────────────────────────────
def _equip_key(s):
    """Chave de casamento equipamento API × planilha: MAIÚSCULO, sem espaços e sem zeros à
    esquerda nos números. Caso real (Rodrigues, 27/08): a API entrega "INVERSOR01" e a aba
    Equipamentos cadastra "INVERSOR 01" — o lookup exato falhava e as esperadas por inversor
    saíam None com o cadastro CERTO dos dois lados. Igualdade da forma normalizada, NUNCA
    substring: "2.1" e "2.18" continuam distintos (o gotcha do deep link, 15/07)."""
    s = re.sub(r"\s+", "", str(s or "")).upper()
    return re.sub(r"(?<!\d)0+(\d)", r"\1", s)


def _equip_lookup(d, nome):
    """d[nome] com tolerância de grafia (ver _equip_key). Exato primeiro — de graça e sem risco."""
    if not d:
        return None
    if nome in d:
        return d[nome]
    k = _equip_key(nome)
    for kk, v in d.items():
        if _equip_key(kk) == k:
            return v
    return None


def _pv_plant_inversores(plant_id):
    """Inversores da usina (API PV) com strings classificadas. Reusado pelo endpoint /api/plant
    e pelo motor de diagnóstico (R-10). Levanta exceção em erro de rede."""
    token = _pv_token_for(plant_id)
    records = _http().post(f"{BASE_URL}/day_inverter",
                            headers={"x-access-token": token},
                            json={"id": plant_id}, timeout=60).json() or []
    if isinstance(records, dict):      # erro da API vem como dict → trata como "sem leitura"
        records = []

    # Busca nome da usina (para lookup no ESPERADO_INV) — SEMPRE (mesmo sem leitura hoje)
    plant_nome_api = ""
    try:
        plants = get_plants(token)
        plant_nome_api = next((p["nome"].strip() for p in plants if p["id"] == plant_id), "")
    except Exception:
        pass

    # Busca nomes dos dispositivos
    dev_names = {}
    try:
        devs_raw = _http().get(f"{BASE_URL}/plant_devices",
                                headers={"x-access-token": token},
                                json={"id": plant_id}, timeout=20).json()
        devs = devs_raw
        if isinstance(devs_raw, list) and devs_raw and "plant_devices" in devs_raw[0]:
            devs = devs_raw[0]["plant_devices"]
        elif isinstance(devs_raw, dict):
            devs = devs_raw.get("plant_devices", [])
        # .strip(): a API às vezes retorna o nome com espaço no fim (ex.: "INVERSOR 04 "),
        # o que quebrava o match com a planilha (nome/esperada caíam no cru). Normaliza aqui.
        dev_names = {d["device_id"]: str(d.get("device_name", "")).strip() for d in devs}
    except Exception:
        pass

    # Usina TODA sem leitura hoje (ex.: 0 geração de madrugada) NÃO pode sumir com os inversores no
    # expand: monta a lista pelo plant_devices, tudo 'desligado' (o loop trata rec=None). Só devolve
    # vazio se não há NEM leitura NEM cadastro de device (planta genuinamente sem inversores).
    if not records and not dev_names:
        return []

    # Registro mais recente por inversor (+ todos os registros do dia p/ fallback de strings)
    latest, by_inv = {}, {}
    for rec in records:
        inv_id = rec.get("idefinversor")
        ts     = rec.get("tsleitura_new", "")
        by_inv.setdefault(inv_id, []).append(rec)
        if inv_id not in latest or ts > latest[inv_id]["tsleitura_new"]:
            latest[inv_id] = rec

    # Usa plant_devices como fonte completa — filtra só inversores reais
    _EXCLUIR_CONTEM = ["x", "old", "velho", "antigo"]

    def eh_inversor(dev_id):
        api_nome_orig = dev_names.get(dev_id, str(dev_id))
        api_nome      = api_nome_orig.lower()
        mapa          = EQUIP_NAMES.get(plant_nome_api, {})
        display_nome  = mapa.get(api_nome_orig, api_nome_orig).lower()
        # Sem plant_devices (conta OEM = "Invalid permission"), o nome do device é o próprio id
        # numérico e o teste do "inv" reprovaria TODOS. Aí quem manda é o day_inverter: todo
        # `idefinversor` com leitura É inversor — a API só reporta inversor nesse endpoint.
        if not dev_names and dev_id in latest:
            return True
        if "inv" not in api_nome and "inv" not in display_nome:
            return False
        for nome in (api_nome, display_nome):
            if any(exc in nome for exc in _EXCLUIR_CONTEM):
                return False
        # O cadastro (BD Equipamentos) é a fonte da verdade dos inversores. Se a usina TEM
        # cadastro e este device não está nele E não tem leitura, é um device avulso/duplicado
        # do supervisório (ex.: "INVERSOR08" fantasma ao lado do "Inversor 2.8" real) → fora.
        if mapa and api_nome_orig not in mapa and dev_id not in latest:
            return False
        return True

    all_ids = sorted(
        [d for d in (dev_names.keys() if dev_names else latest.keys()) if eh_inversor(d)],
        key=(lambda x: dev_names.get(x, str(x))) if dev_names else (lambda x: (len(str(x)), str(x)))
    )

    # Sem plant_devices (conta OEM), a API não entrega NOME de inversor — só o idefinversor. A
    # única chave que sobra é a ORDEM: id crescente ↔ equipamento do cadastro em ordem. Só casa
    # quando a QUANTIDADE bate exatamente; se divergir, não adivinha e mantém o id cru na tela —
    # trocar inversor de nome silenciosamente seria pior que mostrar "INV-378310".
    _pos_map = {}
    if not dev_names:
        _cad = sorted((EQUIP_NAMES.get(plant_nome_api) or {}).keys())
        if _cad and len(_cad) == len(all_ids):
            _pos_map = dict(zip(all_ids, _cad))

    inversores = []
    for inv_id in all_ids:
        inv_nome_api = dev_names.get(inv_id) or _pos_map.get(inv_id) or f"INV-{inv_id}"
        # Traduz para o nome da planilha (Equipamento), mantém API name como fallback
        inv_nome = _equip_lookup(EQUIP_NAMES.get(plant_nome_api), inv_nome_api) or inv_nome_api
        rec      = latest.get(inv_id)          # None se inversor sem dados hoje

        if rec:
            cj = parse_cj(rec.get("conteudojson"))
            ipv_keys  = [k for k in sorted(cj.keys()) if k.startswith("Ipv") and isinstance(cj[k], (int, float))]
            scj = cj
            # O ping mais recente às vezes vem só com Eday/Temp (sem Ipv). Pra um inversor que
            # está gerando não aparecer "0/0" ao expandir, usa o registro mais recente do DIA
            # que tenha corrente por string (dado real) — mantém Eday/Temp/leitura do último.
            if not ipv_keys:
                for prev in sorted(by_inv.get(inv_id, []),
                                   key=lambda r: r.get("tsleitura_new", ""), reverse=True):
                    pcj = parse_cj(prev.get("conteudojson"))
                    pk  = [k for k in sorted(pcj.keys()) if k.startswith("Ipv") and isinstance(pcj[k], (int, float))]
                    if pk:
                        scj, ipv_keys = pcj, pk
                        break
            # String Box: day_inverter expõe ≤1 Ipv por inversor → a corrente por string REAL vem
            # da COMBINER via Plataforma (mesma régua/status; snapshot, como o PG). Inversor de
            # usina String Box SEM combiner exposta (ex.: trocado/recadastrado, id 35xxxx) fica
            # "sem visão": nada de 1 string fantasma virando "-13 faltando" falso.
            eh_combiner = sem_visao = False
            # day_inverter dessas usinas é INCONSTANTE: às vezes ≤1 Ipv, às vezes 24 Ipv quase todas
            # ZERO (Tanabi 23/07 — 1.14/1.16 traziam 24 strings com 1 só corrente real). Em AMBOS os
            # casos a corrente REAL por string está na COMBINER → consulta quando o day_inverter trouxe
            # ≤1 string com corrente DE VERDADE (contar chaves, incl. zeros, deixava a combiner de fora).
            _ipv_reais = sum(1 for k in ipv_keys
                             if isinstance(scj.get(k), (int, float)) and scj[k] > STRING_SEM_CORRENTE_A)
            if _ipv_reais <= 1:
                cmb = _plat_combiner_strings(inv_id)
                if cmb:
                    scj = dict(scj)                       # não polui o cj original (Temp/Eday ficam)
                    scj.update(dict(cmb["strings"]))
                    ipv_keys = [k for k, _ in cmb["strings"]]
                    eh_combiner = True
                elif plant_nome_api in STRING_BOX:
                    sem_visao = True
            correntes = [scj[k] for k in ipv_keys]
            stt       = _classifica_strings(plant_id, inv_id, ipv_keys, correntes)
            strings   = [{"id": k, "corrente": c, "status": s,
                          "ativa": s in ("ativa", "baixa_perf"), "trancada": s == "trancada"}
                         for k, c, s in zip(ipv_keys, correntes, stt)]
            strings_ativas = _str_ativas(stt)
            if sem_visao:                                 # sem visão por string → neutro (sem contagem)
                strings, strings_ativas = [], None
            temp   = cj.get("Temp")
            eday   = cj.get("Eday")
            _pac   = scj.get("Pac")
            # Inversor GERANDO mas com 0 strings ativas. São DUAS causas muito diferentes:
            #  (a) correntes ZERADAS → telemetria de string furada → sem visão, esconde (Levi 13/07:
            #      3.4 Altair 3 — não se gera sem string produzindo);
            #  (b) correntes REAIS, só baixas demais p/ o classificador (mediana < STRING_INV_MIN_MED_A
            #      = "inversor parado") → é a RAMPA de início/fim de dia. Esconder aqui APAGAVA strings
            #      que existem e que o operador vê no PV Operation (Mandaguaçu 22/07 08:14: Pac 2,6 kW
            #      com as 12 strings a ~0,31 A). Agora MOSTRA as correntes e só neutraliza a CONTAGEM,
            #      que é o que evitava o "-240 faltando" falso.
            rampa = False
            if (not sem_visao and (eh_combiner or plant_nome_api in STRING_BOX)
                    and strings_ativas == 0 and isinstance(_pac, (int, float)) and _pac >= MACRO_POT_INV_MIN):
                if any(isinstance(c, (int, float)) and c > STRING_SEM_CORRENTE_A for c in correntes):
                    rampa, strings_ativas = True, None       # (b) dado real: exibe, não conta
                else:
                    sem_visao = True                          # (a) tudo zero gerando: telemetria furada
                    strings, strings_ativas = [], None
            ts_rec = rec.get("tsleitura_new", "")
            falha  = False
            if ts_rec:
                try:
                    diff = (datetime.now() - datetime.strptime(ts_rec, "%Y-%m-%d %H:%M:%S")).total_seconds() / 60
                    falha = diff > COMM_ALERT_MINUTES
                except Exception:
                    pass
            desligado = False
        else:
            # Inversor desligado / sem comunicação hoje
            strings        = []
            strings_ativas = 0
            temp           = None
            eday           = None
            _pac           = None
            ts_rec         = None
            falha          = True
            desligado      = True
            eh_combiner    = False
            sem_visao      = False
            rampa          = False

        # Lookup de strings esperadas usa o nome da API (chave original da planilha).
        # `rampa` também neutraliza a contagem (as strings aparecem, mas não viram "faltando").
        inv_str_esp   = None if (sem_visao or rampa) else _equip_lookup(ESPERADO_INV.get(plant_nome_api), inv_nome_api)
        inv_diferenca = (strings_ativas - inv_str_esp) \
            if (inv_str_esp is not None and not desligado and isinstance(strings_ativas, (int, float))) else None

        inversores.append({
            "id": inv_id,
            "nome": inv_nome,
            "nome_api": inv_nome_api,
            "ultima_leitura": ts_rec,
            "falha_comunicacao": falha,
            "desligado": desligado,
            "active_power": _pac,
            "strings_ativas": strings_ativas,
            "total_strings": len(strings),
            "str_esp": inv_str_esp,
            "diferenca": inv_diferenca,
            "temp": temp,
            "eday": eday,
            "combiner": eh_combiner,     # strings vieram da COMBINER (Plataforma) — usina String Box
            "sem_visao": sem_visao,      # String Box sem combiner exposta → sem contagem (neutro)
            "rampa": rampa,              # correntes reais porém baixas (amanhecer/anoitecer) → exibe, não conta
            "strings": strings,
        })

    # Deduplica por nome_api: se mesmo inversor aparecer duplicado, fica o com dados
    seen = {}
    for inv in inversores:
        key = inv.get("nome_api", inv["nome"])
        if key not in seen:
            seen[key] = inv
        elif seen[key].get("desligado") and not inv.get("desligado"):
            seen[key] = inv
    inversores = list(seen.values())

    # ── Inversor DESLIGADO de dia (MESMA régua do PG): potência ativa (Pac) ~0 → inversor parado.
    # A régua por-inversor (_classifica_strings) marca tudo "inativa" (parece noite) → o heatmap
    # pintava VERDE e o card contava como OK. De dia, Pac~0 = trip/desligamento real → linha inteira
    # vira 'desligado' (a corrente reversa residual não é produção). Fallback (sem Pac): régua antiga
    # por strings (≥2 inversores gerando = usina produz; inversor 100% sem corrente = desligado).
    _dia = 7 <= datetime.now().hour < 18
    _prod, _potmed, _ = _macro_prod([inv.get("active_power") for inv in inversores])
    _tem_pac = any(isinstance(inv.get("active_power"), (int, float)) for inv in inversores)
    _plant_prod = len([inv for inv in inversores if (inv.get("strings_ativas") or 0) > 0]) >= 2
    for inv, pr in zip(inversores, _prod):
        if _tem_pac:
            _off = pr is False and _dia
        else:                                     # fallback sem Pac: só se a usina está gerando
            _off = _plant_prod and (inv.get("strings_ativas") or 0) == 0
        if _off and any(s["status"] != "trancada" for s in inv["strings"]):
            inv["desligado"] = True
            for s in inv["strings"]:
                if s["status"] != "trancada":
                    s["status"] = "desligado"; s["ativa"] = False
    return inversores


@app.route("/api/plant/<int:plant_id>")
def api_plant_detail(plant_id):
    try:
        invs = _pv_plant_inversores(plant_id)
    except Exception as e:
        # Antes o rótulo era sempre "timeout", e não era: um id inexistente faz a API PV devolver
        # 401 {"error": "Invalid id"} — um DICT. O código então iterava as CHAVES do dict e morria
        # com AttributeError, que virava "timeout" na tela e mandava investigar rede à toa.
        return jsonify({"error": "falha", "detalhe": f"{type(e).__name__}: {e}"}), 504
    return jsonify({"plant_id": plant_id, "inversores": invs})


@app.route("/api/pv/grupo/<int:plant_id>")
def api_pv_grupo(plant_id):
    """Plantas IRMÃS da mesma usina física no API PV.

    Nova Londrina é UMA usina para quem opera, mas está cadastrada como duas plantas
    (`Nova Londrina 1 (152)` = id 22854 e `Nova Londrina 2 (153)` = id 22855). O portfólio já
    junta as duas pelo USINA_GRUPO; o drill abria só a que foi clicada e os 10 inversores da
    2 sumiam da tela — quem olhava via 8 inversores e concluía que a usina tinha 8.

    Os nomes de inversor não colidem (`Inversor 1.x` × `Inversor 2.x`), então quem consome pode
    concatenar sem prefixar. Vale para qualquer usina fatiada assim, não só Nova Londrina.
    """
    try:
        plants = get_plants(get_token())
    except Exception as e:
        return jsonify({"error": f"{type(e).__name__}: {e}", "membros": []}), 502

    def _grupo_de(nome):
        n = (nome or "").strip()
        return USINA_GRUPO.get(n) or n

    atual = next((p for p in plants if p["id"] == plant_id), None)
    if not atual:
        return jsonify({"grupo": None, "membros": []})
    grupo = _grupo_de(atual["nome"])
    membros = sorted(({"id": p["id"], "nome": (p["nome"] or "").strip()}
                      for p in plants if _grupo_de(p["nome"]) == grupo),
                     key=lambda m: m["nome"])
    return jsonify({"grupo": grupo, "membros": membros})


