# ── Geração PIVÔ por inversor (tabela "Geração", últimos N dias) ───────────────
#   Uma linha por (usina, dia): POA/GHI (kWh/m², integração trapezoidal — mesma régua do
#   /api/pg/geracao) + geração de CADA inversor no dia (MAX(daily_active_energy), o acumulado
#   que zera 0h) pivotada lado a lado + total. Pluviômetro ainda não vem do BD_Thopen (fica —).
#   Esqueleto multi-fonte: por enquanto só o Banco de Dados (pg) devolve dados.
_pg_gerpivo_cache = {}
_pg_gerpivo_lock  = threading.Lock()


def _pg_geracao_pivo(start: str, end: str):
    sql = """
      WITH lidos AS (     -- dbt congelado → geração por inversor do CRU public.raw_inverter
        -- Mesma régua do _pg_geracao_periodo (ver comentário lá): o contador diário não zera à
        -- meia-noite, então só vale do RESET do dia em diante. Era ESTA tela que mostrava dias
        -- consecutivos com geração idêntica (Levi 07/08, Aparecida 3).
        SELECT a.power_plant_id AS pid, a.device_id AS did, d.device_name AS dev,
               (a.timestamp AT TIME ZONE 'America/Sao_Paulo') AS ts,
               (a.timestamp AT TIME ZONE 'America/Sao_Paulo')::date AS dia,
               (a.json_data->>'daily_active_energy')::numeric AS dae,
               LAG((a.json_data->>'daily_active_energy')::numeric)
                 OVER (PARTITION BY a.power_plant_id, a.device_id ORDER BY a.timestamp) AS dae_prev
        FROM public.raw_inverter a
        JOIN public.tb_devices d ON d.id = a.device_id
        WHERE a.timestamp >= (%(start)s::date)::timestamp AT TIME ZONE 'America/Sao_Paulo'
          AND a.timestamp <  ((%(end)s::date)+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'
      ),
      ciclo AS (
        SELECT *, MIN(ts) FILTER (WHERE dae_prev IS NOT NULL AND dae < dae_prev - 1)
                    OVER (PARTITION BY pid, did, dia) AS t_reset
        FROM lidos
      ),
      gen AS (
        SELECT pid, dia, dev, MAX(dae) FILTER (WHERE t_reset IS NULL OR ts >= t_reset) AS ger
        FROM ciclo GROUP BY pid, dia, dev
      ),
      pts AS (            -- irradiância do CRU public.raw_weather_station
        SELECT power_plant_id, (timestamp AT TIME ZONE 'America/Sao_Paulo')::date AS dia,
               (timestamp AT TIME ZONE 'America/Sao_Paulo') AS ts,
               (json_data->>'irradiance_poa')::numeric AS poa, (json_data->>'irradiance_ghi')::numeric AS ghi,
               LAG((timestamp AT TIME ZONE 'America/Sao_Paulo'))       OVER w AS pts_prev,
               LAG((json_data->>'irradiance_poa')::numeric) OVER w AS poa_prev,
               LAG((json_data->>'irradiance_ghi')::numeric) OVER w AS ghi_prev
        FROM public.raw_weather_station
        WHERE timestamp >= (%(start)s::date)::timestamp AT TIME ZONE 'America/Sao_Paulo'
          AND timestamp <  ((%(end)s::date)+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'
        WINDOW w AS (PARTITION BY power_plant_id, (timestamp AT TIME ZONE 'America/Sao_Paulo')::date ORDER BY timestamp)
      ),
      irr AS (
        SELECT power_plant_id, dia,
               ROUND(SUM(CASE WHEN pts_prev IS NOT NULL AND EXTRACT(EPOCH FROM (ts-pts_prev)) <= %(gapcap)s
                         THEN (poa+poa_prev)/2.0 * EXTRACT(EPOCH FROM (ts-pts_prev))/3600.0 ELSE 0 END)/1000.0, 2) AS poa,
               ROUND(SUM(CASE WHEN pts_prev IS NOT NULL AND EXTRACT(EPOCH FROM (ts-pts_prev)) <= %(gapcap)s
                         THEN (ghi+ghi_prev)/2.0 * EXTRACT(EPOCH FROM (ts-pts_prev))/3600.0 ELSE 0 END)/1000.0, 2) AS ghi
        FROM pts GROUP BY power_plant_id, dia
      )
      SELECT p.name, g.pid, g.dia, g.dev, g.ger, i.poa, i.ghi
      FROM gen g
      LEFT JOIN irr i ON i.power_plant_id = g.pid AND i.dia = g.dia
      LEFT JOIN public.tb_power_plants p ON p.id = g.pid
      ORDER BY p.name, g.dia, g.dev;
    """
    conn = _pg_conn(); cur = conn.cursor()
    cur.execute(sql, {"start": start, "end": end, "gapcap": PG_IRR_GAP_CAP_MIN * 60})
    recs = cur.fetchall(); conn.close()
    usinas = {}
    for nome, pid, dia, dev, ger, poa, ghi in recs:
        sup = (nome or f"Usina {pid}").strip()
        u = usinas.setdefault(pid, {"plant_id": pid, "usina": USINA_DISPLAY.get(sup, sup),
                                    "_invs": {}, "_dias": {}})
        u["_invs"][dev] = (EQUIP_NAMES.get(sup, {}) or {}).get(dev, dev)
        d = u["_dias"].setdefault(str(dia), {"data": str(dia),
                                             "poa": float(poa) if poa is not None else None,
                                             "ghi": float(ghi) if ghi is not None else None,
                                             "pluviometro": None, "ger": {}})
        if ger is not None:
            d["ger"][dev] = round(float(ger), 1)
    out = []
    for pid, u in usinas.items():
        devs = sorted(u["_invs"].keys(), key=lambda x: _pv_trk_num(x))
        cols = [{"dev": dv, "nome": u["_invs"][dv]} for dv in devs]
        dias = sorted(u["_dias"].values(), key=lambda x: x["data"], reverse=True)
        pot_kwp = (INFO_GERAL.get(_nrm(u["usina"])) or {}).get("potencia_kwp")
        for d in dias:
            d["ger_total"] = round(sum(d["ger"].values()), 1) if d["ger"] else None
            # PR do DIA = geração ÷ (potência × POA), a régua clássica. Só com POA utilizável
            # (>0,3 kWh/m² — mesma trava do Dashboard de PR): POA quebrada daria PR de 300%.
            # Sem potência no cadastro (usina fora da Info Geral) o PR fica None, não 0.
            pr = None
            if pot_kwp and d.get("poa") and d["poa"] > 0.3 and d.get("ger_total"):
                pr = d["ger_total"] / (pot_kwp * d["poa"]) * 100
            d["pr"] = round(pr, 1) if pr is not None else None
        out.append({"plant_id": pid, "usina": u["usina"], "inversores": cols, "dias": dias})
    out.sort(key=lambda x: x["usina"])
    return out


def _gerpivo_periodo(dias_default=10):
    # Janela = últimos N dias COMPLETOS (termina ONTEM, como o /api/pg/geracao): evita a linha do dia
    # corrente com geração parcial + irradiância ainda não fechada (POA/GHI zerados).
    hoje = datetime.now().date()
    try:
        n = max(1, min(31, int(flask_request.args.get("dias", dias_default))))
    except ValueError:
        n = dias_default
    return (hoje - timedelta(days=n)).isoformat(), (hoje - timedelta(days=1)).isoformat()


def _gerpivo_janela():
    """Janela do pivô de Geração: ?ini/?fim explícitos (De/Até da tela) ou o default acima.
    Usada TAMBÉM pelos exports — o XLSX baixado tem de mostrar a mesma janela que a tela.
    Teto de 31 dias: janela escolhida não é pré-aquecida (roda na requisição) e a consulta
    cresce linear com os dias. Fim é capado em HOJE; incluir o dia corrente é escolha do
    usuário (a linha sai parcial, e é dado honesto)."""
    ini_q = (flask_request.args.get("ini") or "").strip()
    fim_q = (flask_request.args.get("fim") or "").strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}$", ini_q) and re.match(r"^\d{4}-\d{2}-\d{2}$", fim_q):
        try:
            a = datetime.strptime(min(ini_q, fim_q), "%Y-%m-%d").date()
            b = datetime.strptime(max(ini_q, fim_q), "%Y-%m-%d").date()
            hoje = datetime.now().date()
            b = min(b, hoje)
            if (b - a).days > 30:
                a = b - timedelta(days=30)
            return a.isoformat(), b.isoformat()
        except ValueError:
            pass
    return _gerpivo_periodo()


def _pg_gerpivo_get(start, end, force=False):
    key = f"{start}|{end}"
    with _pg_gerpivo_lock:
        ent = _pg_gerpivo_cache.get(key)
        if not force and ent and (time.time() - ent["ts"]) < CACHE_TTL:
            return ent["data"]
    data = _pg_geracao_pivo(start, end)
    with _pg_gerpivo_lock:
        _pg_gerpivo_cache[key] = {"ts": time.time(), "data": data}
    return data


_GERPIVO_MSG = ("Geração por inversor + POA/GHI ainda só no Banco de Dados (Thopen) — "
                "em construção nas demais fontes.")


@app.route("/api/<fonte>/geracao-pivo")
def api_geracao_pivo(fonte):
    if fonte != "pg":
        return jsonify({"usinas": [], "indisponivel": True, "msg": _GERPIVO_MSG,
                        "cache_ts": datetime.now().strftime("%H:%M:%S")})
    start, end = _gerpivo_janela()
    try:
        usinas = _pg_gerpivo_get(start, end, force=flask_request.args.get("force") == "1")
    except Exception as e:
        return jsonify({"error": str(e), "usinas": []}), 500
    return jsonify({"usinas": usinas, "start": start, "end": end,
                    "cache_ts": datetime.now().strftime("%H:%M:%S")})


@app.route("/api/<fonte>/geracao-pivo/export")
def api_geracao_pivo_export(fonte):
    if fonte != "pg":
        return jsonify({"error": "indisponível nesta fonte"}), 400
    start, end = _gerpivo_janela()
    try:
        blocks = _pg_gerpivo_get(start, end)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    recs = []
    for b in blocks:
        for d in b["dias"]:
            for col in b["inversores"]:
                recs.append({"Usina": b["usina"], "Data": d["data"],
                             "POA (kWh/m²)": d["poa"], "GHI (kWh/m²)": d["ghi"],
                             "Pluviômetro (mm)": d["pluviometro"],
                             "Inversor": col["nome"], "Geração (kWh)": d["ger"].get(col["dev"])})
    cols = ["Usina", "Data", "POA (kWh/m²)", "GHI (kWh/m²)", "Pluviômetro (mm)",
            "Inversor", "Geração (kWh)"]
    df = pd.DataFrame(recs, columns=cols)
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as xl:
        df.to_excel(xl, index=False, sheet_name="Geração por inversor")
        ws = xl.sheets["Geração por inversor"]
        for col_cells in ws.columns:
            largura = max((len(str(c.value)) for c in col_cells if c.value is not None), default=10)
            ws.column_dimensions[col_cells[0].column_letter].width = min(largura + 3, 40)
    buf.seek(0)
    return send_file(buf, as_attachment=True,
                     download_name=f"geracao_inversor_PG_{start}_a_{end}.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


def _xl_sheet(name, used):
    """Nome de aba Excel válido e único (<=31 chars, sem [ ] : * ? / \\)."""
    s = re.sub(r"[\[\]:*?/\\]", " ", str(name or "Usina")).strip()[:31] or "Usina"
    base, i = s[:28], 2
    while s in used:
        s = f"{base}~{i}"; i += 1
    used.add(s)
    return s


def _xl_autofit(ws, teto=40):
    for cc in ws.columns:
        w = max((len(str(c.value)) for c in cc if c.value is not None), default=10)
        ws.column_dimensions[cc[0].column_letter].width = min(w + 2, teto)


@app.route("/api/<fonte>/geracao-pivo/export-usinas")
def api_geracao_pivo_export_usinas(fonte):
    """XLSX de Geração com UMA ABA POR USINA (Data, POA, GHI, Pluviômetro, inversores, Total)."""
    if fonte != "pg":
        return jsonify({"error": "indisponível nesta fonte"}), 400
    start, end = _gerpivo_janela()
    try:
        blocks = _pg_gerpivo_get(start, end)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    buf, used = io.BytesIO(), set()
    with pd.ExcelWriter(buf, engine="openpyxl") as xl:
        for b in sorted(blocks, key=lambda x: x["usina"]):
            invs = b["inversores"]
            recs = []
            for d in b["dias"]:
                row = {"Data": d["data"], "POA (kWh/m²)": d["poa"], "GHI (kWh/m²)": d["ghi"],
                       "Pluviômetro (mm)": d["pluviometro"]}
                for col in invs:
                    row[col["nome"]] = d["ger"].get(col["dev"])
                row["Total (kWh)"] = d.get("ger_total")
                recs.append(row)
            cols = (["Data", "POA (kWh/m²)", "GHI (kWh/m²)", "Pluviômetro (mm)"]
                    + [c["nome"] for c in invs] + ["Total (kWh)"])
            sh = _xl_sheet(b["usina"], used)
            pd.DataFrame(recs, columns=cols).to_excel(xl, index=False, sheet_name=sh)
            _xl_autofit(xl.sheets[sh])
    buf.seek(0)
    return send_file(buf, as_attachment=True,
                     download_name=f"geracao_por_usina_PG_{start}_a_{end}.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.route("/api/<fonte>/etm-pivo/export")
def api_etm_pivo_export(fonte):
    """XLSX ETM: aba POA e aba GHI, cada uma pivô usina (linhas) × dias da janela (colunas)."""
    if fonte != "pg":
        return jsonify({"error": "indisponível nesta fonte"}), 400
    start, end = _gerpivo_janela()
    try:
        blocks = _pg_gerpivo_get(start, end)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    datas = sorted({d["data"] for b in blocks for d in b["dias"]})

    def _piv(campo):
        recs = []
        for b in sorted(blocks, key=lambda x: x["usina"]):
            byd = {d["data"]: d.get(campo) for d in b["dias"]}
            row = {"Usina": b["usina"]}
            for dt in datas:
                row[dt] = byd.get(dt)
            recs.append(row)
        return pd.DataFrame(recs, columns=["Usina"] + datas)
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as xl:
        for campo, sh in (("poa", "POA"), ("ghi", "GHI")):
            _piv(campo).to_excel(xl, index=False, sheet_name=sh)
            _xl_autofit(xl.sheets[sh], teto=16)
    buf.seek(0)
    return send_file(buf, as_attachment=True,
                     download_name=f"etm_poa_ghi_PG_{start}_a_{end}.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


# ── Estado compartilhado: verificação + comentários por usina ──────────────────
STATE_PATH  = os.path.join(_AQUI, "ufv_state.json")
_state_lock = threading.Lock()


def _load_state() -> dict:
    try:
        with open(STATE_PATH, encoding="utf-8") as f:
            d = json.load(f)
    except Exception:
        d = {}
    d.setdefault("verified", [])   # lista de chaves (ex.: "pv:22854", "so:CPP100")
    d.setdefault("comments", {})          # {chave: texto} (legado, 1 comentário sobrescrito)
    d.setdefault("comments_thread", {})   # {chave: [{nick, texto, ts}]} (thread multi-analista)
    d.setdefault("tracking", {})   # {chave: int}  → strings em acompanhamento
    d.setdefault("manutencao", [])  # lista de chaves de ETM em manutenção (ex.: "etm:pv:22854")
    d.setdefault("strings_trancadas", [])  # chaves "plant_id|inv_id|Ipv" de strings trancadas (MPPT sem string)
    d.setdefault("etm_tickets", {})   # {usina_nrm: {usina, comentario, feito, ts}} — visão ETM da Frota
    d.setdefault("os_atribuidas", {})  # {"plant_id|inv_id": {usina,usina_nrm,inv,folio,ativo,desc,criada,evento,status,nick,ts}} — OS do Fracttal grudada num inversor sem geração
    return d


def _save_state(d: dict) -> None:
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    _replace_atomico(tmp, STATE_PATH)   # gravação atômica


_trancadas = set(_load_state().get("strings_trancadas", []))   # carga inicial em memória

# Índice tolerante ao plant_id: {(inv_id, "IpvN")} das trancadas. inv_id (idefinversor) é ÚNICO GLOBAL
# na API PV → uma string trancada num inversor vale onde quer que esse inversor apareça, mesmo que a
# trava tenha sido gravada sob um plant_id de outro namespace (ex.: usina em 3 registros — Fernandópolis).
_TRANC_INV = set()
def _rebuild_tranc_inv():
    global _TRANC_INV
    s = set()
    for k in _trancadas:
        p = k.split("|")
        if len(p) == 3 and p[2].startswith("Ipv"):
            s.add((p[1], p[2]))
    _TRANC_INV = s
_rebuild_tranc_inv()

def _str_trancada(plant_id, inv_id, ipv):
    """True se a string está trancada — casamento EXATO (plant_id|inv_id|ipv) OU tolerante ao plant_id
    (inv_id|ipv), pra não vazar quando a mesma usina tem plant_ids diferentes entre trava e leitura."""
    return _str_key(plant_id, inv_id, ipv) in _trancadas or (str(inv_id), ipv) in _TRANC_INV


@app.route("/api/state")
def api_state_get():
    with _state_lock:
        return jsonify(_load_state())


@app.route("/api/state/string-trancada", methods=["POST"])
def api_state_string_trancada():
    """Marca/desmarca uma string como 'trancada' (MPPT sem string conectada). Persiste no
    estado e atualiza o set em memória (usado por _classifica_strings)."""
    global _trancadas
    body     = flask_request.get_json(force=True, silent=True) or {}
    plant_id = str(body.get("plant_id", "")).strip()
    inv_id   = str(body.get("inv_id", "")).strip()
    trancada = bool(body.get("trancada"))
    # Aceita uma string (compat) OU uma lista 'strings' (trancar/destrancar em lote,
    # ex.: o botão "Trancar strings inativas" do inversor).
    raw      = body.get("strings")
    nomes    = ([str(x).strip() for x in raw if str(x).strip()] if isinstance(raw, list)
                else [str(body.get("string", "")).strip()])
    nomes    = [n for n in nomes if n]
    if not (plant_id and inv_id and nomes):
        return jsonify({"error": "plant_id, inv_id e string(s) obrigatórios"}), 400
    with _state_lock:
        d = _load_state()
        s = set(d.get("strings_trancadas", []))
        for nm in nomes:
            key = f"{plant_id}|{inv_id}|{nm}"
            s.add(key) if trancada else s.discard(key)
        d["strings_trancadas"] = sorted(s)
        _save_state(d)
        _trancadas = s
        _rebuild_tranc_inv()
    # As curvas de strings excluem as trancadas → invalida os caches da usina afetada
    # (API PV e SunOp) p/ a próxima abertura do gráfico recomputar já sem a string.
    # O ck[0] é o id da usina em ambos (idusina / plant_name) = o plant_id do POST.
    # PG não tem cache de curva (recomputa do banco a cada chamada).
    for ck in [ck for ck in _spv_cache if str(ck[0]) == plant_id]:
        _spv_cache.pop(ck, None)
    for ck in [ck for ck in _sunop_curva_cache if str(ck[0]) == plant_id]:
        _sunop_curva_cache.pop(ck, None)
    # As sub-abas OCORRÊNCIAS e SEM-CORRENTE também excluem as trancadas, mas SERVEM DE CACHE (rows já
    # calculadas). Sem invalidar, a string recém-trancada segue aparecendo até o TTL (5min hoje;
    # PERMANENTE em dia passado da API PV). Levi 08/07: "trancada não pode aparecer nas 2 abas". (PG e
    # 2C reaplicam a régua na LEITURA → não precisam.)
    _str_prob_pv_cache["rows"] = None                    # sem-corrente API PV
    _pv_str_ev_cache.clear()                             # ocorrências API PV (todas as datas)
    _sunop_str_ev_cache.clear()                          # ocorrências SunOp/Axis
    for _c in (_sunop_str_med_cache, _pg_str_med_cache, _axis_str_med_cache):
        for _ck in [c for c in _c if str(c[0]) == plant_id]:
            _c.pop(_ck, None)
    return jsonify({"ok": True, "trancadas": len(s)})


@app.route("/api/state/os-atribuir", methods=["POST"])
def api_state_os_atribuir():
    """Gruda uma OS do Fracttal num inversor sem geração (chave plant_id|inv_id). A OS passa a aparecer
    no card de comentários da usina, junto com as de Performance, até ser concluída no Fracttal."""
    body   = flask_request.get_json(force=True, silent=True) or {}
    pid    = str(body.get("pid", "")).strip()
    inv_id = str(body.get("inv_id", "")).strip()
    folio  = str(body.get("folio", "")).strip()
    usina  = str(body.get("usina", "")).strip()
    if not (pid and inv_id and folio and usina):
        return jsonify({"error": "pid, inv_id, folio e usina obrigatórios"}), 400
    key = f"{pid}|{inv_id}"
    rec = {"usina": usina, "usina_nrm": _nrm(usina), "inv": str(body.get("inv_nome", "")).strip(),
           "folio": folio, "ativo": str(body.get("ativo", "")).strip(),
           "desc": str(body.get("desc", "")).strip(), "criada": str(body.get("criada", "")).strip(),
           "evento": str(body.get("evento", "")).strip(), "status": str(body.get("status", "")).strip(),
           "responsavel": str(body.get("responsavel", "")).strip(),   # responsável da OS (vira o da OS filha no deep link)
           "nick": str(body.get("nick", "")).strip()[:40] or "—",
           "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
    with _state_lock:
        d = _load_state()
        d.setdefault("os_atribuidas", {})[key] = rec
        _save_state(d)
    return jsonify({"ok": True, "key": key, "rec": rec})


