_FRAC_INDEX_FILE = os.path.join(_AQUI, "fracttal_index.json")


def _frac_codebase_index():
    """{groups_1_description.lower → {'cb': code-base, 'site': id_item da raiz}} dos ativos
    Fracttal (item_type=1). 1x (lazy), cacheado. 'cb' de qualquer ativo (regex XXX###); 'site'
    do ativo cujo code é "PREFIXO-CODEBASE" (raiz da usina) — usado p/ contar OS no badge.
    PERSISTIDO em disco: paginar o parque inteiro custa ~150 requests na Fracttal, e o cache em
    memória morria a cada restart do servidor — o arquivo evita repagar dentro do TTL."""
    global _frac_cb_index, _frac_cb_ts
    if _frac_cb_index and (time.time() - _frac_cb_ts) < FRAC_CODE_TTL:
        return _frac_cb_index
    if not _frac_cb_index:                     # boot frio → tenta o índice salvo antes de ir à API
        try:
            with open(_FRAC_INDEX_FILE, encoding="utf-8") as f:
                d = json.load(f)
            if d.get("idx") and (time.time() - d.get("ts", 0)) < FRAC_CODE_TTL:
                _frac_cb_index, _frac_cb_ts = d["idx"], d["ts"]
                return _frac_cb_index
        except Exception:
            pass
    idx, start = {}, 0
    while True:
        d = _frac_get("items/", item_type=1, start=start, limit=200)
        page = (d.get("data") if isinstance(d, dict) else d) or []
        if not page:
            break
        for it in page:
            code = str(it.get("code") or "")
            cb = re.search(r"[A-Z]{3}\d{3}", code)
            g1 = str(it.get("groups_1_description") or "").strip().lower()
            if not (cb and g1):
                continue
            ent = idx.setdefault(g1, {"cb": cb.group(0), "site": None})
            parts = code.split("-")
            if ent["site"] is None and len(parts) == 2 and re.fullmatch(r"[A-Z]{3}\d{3}", parts[1]):
                ent["site"] = it.get("id")
        total = d.get("total") if isinstance(d, dict) else None
        start += len(page)
        if (total and start >= total) or start > 30000:
            break
    if idx:
        _frac_cb_index, _frac_cb_ts = idx, time.time()
        try:
            with open(_FRAC_INDEX_FILE, "w", encoding="utf-8") as f:
                json.dump({"ts": _frac_cb_ts, "idx": idx}, f, ensure_ascii=False)
        except Exception as e:
            print(f"[fracttal] não consegui salvar o índice: {e}")
    elif not _frac_cb_index:                   # API falhou e sem memória → índice salvo mesmo velho
        try:
            with open(_FRAC_INDEX_FILE, encoding="utf-8") as f:
                d = json.load(f)
            if d.get("idx"):
                print("[fracttal] API indisponível — usando índice salvo (stale)")
                _frac_cb_index, _frac_cb_ts = d["idx"], time.time() - FRAC_CODE_TTL + 600
        except Exception:
            pass
    return _frac_cb_index


def _frac_usina_ent(usina):
    """Entrada do índice ({cb, site}) p/ a usina do dashboard: nome → 'Usina Fractall' → índice."""
    desc = _frac_fractall_map().get(str(usina or "").strip().lower())
    return _frac_codebase_index().get(desc.strip().lower()) if desc else None


def _frac_codebase(usina):
    """Code-base Fracttal (ex. CPP100/CXB100) a partir do nome da usina no dashboard. Athon: o
    nome JÁ é o code-base; demais (Thopen…): nome → 'Usina Fractall' (BD) → code-base (índice)."""
    s = str(usina or "").strip()
    if not s:
        return None
    if re.fullmatch(r"[A-Za-z]{3}\d{3}", s):       # já é um code-base (CPP100, TIM100, MAB200…)
        return s.upper()
    ent = _frac_usina_ent(s)
    return ent.get("cb") if ent else None


def _frac_inv_code(usina, inv_disp):
    """Code Fracttal do inversor: "{CODE-BASE}-INVR{N.M}" (N.M do display "Inversor N.M")."""
    m = re.search(r"\d+\.\d+|\d+", str(inv_disp or ""))
    base = _frac_codebase(usina)
    return f"{base}-INVR{m.group(0)}" if (m and base) else None


def _frac_ativo(code):
    """Resolve um code Fracttal → {id, desc} via items/{code} (cacheado). None se não existir."""
    ent = _frac_code_cache.get(code)
    if ent and (time.time() - ent["ts"]) < FRAC_CODE_TTL:
        return ent["ativo"]
    d = _frac_get(f"items/{code}")
    data = (d.get("data") if isinstance(d, dict) else d) or []
    it = data[0] if isinstance(data, list) and data else (data if isinstance(data, dict) and data else None)
    ativo = {"id": it.get("id"), "desc": str(it.get("description") or "").split("  ")[0].strip()} if it else None
    _frac_code_cache[code] = {"ts": time.time(), "ativo": ativo}
    return ativo


def _frac_os_de(id_item, n=5):
    """Últimas n OS de um ativo (dedup por folio, mais recentes 1º). Cacheado FRAC_OS_TTL."""
    ent = _frac_os_cache.get(id_item)
    if not (ent and (time.time() - ent["ts"]) < FRAC_OS_TTL):
        d = _frac_get("work_orders/", id_item=id_item, limit=200)
        rows = (d.get("data") if isinstance(d, dict) else d) or []
        seen = {}
        for w in rows:
            seen.setdefault(w.get("wo_folio"), w)
        wos = sorted(seen.values(), key=lambda w: str(w.get("creation_date") or ""), reverse=True)

        def _dloc(s, com_hora=False):
            # Fracttal manda UTC; cortar [:10] direto erra o DIA para tudo que acontece depois das
            # 21h locais (00Z+). Mesma conversão da régua de RDO (_frac_dt_local).
            dt = _frac_dt_local(s)
            return (dt.strftime("%d/%m/%Y %H:%M") if com_hora else dt.strftime("%d/%m/%Y")) if dt else None

        data = [{"folio": w.get("wo_folio"),
                 "descricao": str(w.get("description") or "").strip(),
                 "status": FRAC_WO_STATUS.get(w.get("id_status_work_order"), "—"),
                 "aberta": w.get("id_status_work_order") in (0, 1, 5, 6),
                 "criada": str(w.get("creation_date") or "")[:10],
                 # pedidos do Levi 26/08 p/ o histórico de ETM: evento, início/fim reais e autoria
                 "evento": _dloc(w.get("event_date")),
                 "inicio": _dloc(w.get("initial_date")),
                 "fim": _dloc(w.get("final_date") or w.get("wo_final_date")),
                 "criada_por": str(w.get("requested_by") or "").strip() or None,
                 "criada_em": _dloc(w.get("creation_date"), com_hora=True),
                 "responsavel": str(w.get("personnel_description") or w.get("user_assigned") or "").strip() or None,
                 } for w in wos]
        ent = {"ts": time.time(), "data": data}
        _frac_os_cache[id_item] = ent
    return ent["data"][:n]


# ── OSs de PERFORMANCE por usina, do FRACTTAL (etiqueta "PERFORMANCE") ───────────────────────────
# O Levi quer as OSs REAIS do Fracttal (NÃO a planilha de Tickets), casadas ao supervisório pela aba
# Equipamentos do BD (Usina Fractall). O os_creator cria as de Performance com a ETIQUETA id 4660
# ("PERFORMANCE"). As 'em andamento' (status 1) têm MUITA MPM/religamento junto (ruído) → filtramos só
# as com essa etiqueta. O filtro por label no REST da Fracttal é IGNORADO → varre e filtra local, num
# índice cacheado/persistido (o sweep custa ~19 requests).
FRAC_OS_PERF_LABEL = 4660
_frac_osperf_idx = {}
_frac_osperf_ts = 0.0
_frac_openwo_idx = {}          # {Usina Fractall (norm) → [TODAS as OS abertas]} — pick-list do "Atribuir OS"
_FRAC_OSPERF_FILE = os.path.join(_AQUI, "frac_osperf_index.json")
FRAC_OSPERF_TTL = 30 * 60


def _frac_grpkey(s):
    return re.sub(r"\s+", " ", str(s or "")).strip().lower()


def _frac_osperf_index(force=False):
    """{Usina Fractall (norm) → [OSs de Performance EM ABERTO]}. Varre work_orders status=1, mantém só as
    com a etiqueta PERFORMANCE (4660), agrupa por groups_1_description (= Usina Fractall). Cacheado 30 min
    + persistido (boot frio lê o arquivo)."""
    global _frac_osperf_idx, _frac_osperf_ts, _frac_openwo_idx
    if not force and _frac_osperf_idx and (time.time() - _frac_osperf_ts) < FRAC_OSPERF_TTL:
        return _frac_osperf_idx
    if not force and not _frac_osperf_idx:
        try:
            with open(_FRAC_OSPERF_FILE, encoding="utf-8") as f:
                d = json.load(f)
            if d.get("idx") and (time.time() - d.get("ts", 0)) < FRAC_OSPERF_TTL:
                _frac_osperf_idx, _frac_osperf_ts = d["idx"], d["ts"]
                _frac_openwo_idx = d.get("openwo") or {}
                return _frac_osperf_idx
        except Exception:
            pass
    idx, openidx, start = {}, {}, 0
    try:
        while start < 8000:
            d = _frac_get("work_orders/", id_status_work_order=1, start=start, limit=200)
            rows = (d.get("data") if isinstance(d, dict) else d) or []
            if not rows:
                break
            for w in rows:
                g = _frac_grpkey(w.get("groups_1_description"))
                if g:                              # TODAS as abertas (não só as de Performance) → pick-list do "Atribuir OS"
                    openidx.setdefault(g, []).append({
                        "folio": w.get("wo_folio"),
                        "ativo": _frac_ativo_curto(w.get("items_log_description") or ""),
                        "desc": str(w.get("description") or "").strip(),
                        "criada": str(w.get("creation_date") or "")[:10],
                        "evento": str(w.get("event_date") or w.get("date_maintenance") or "")[:10],
                        "status": FRAC_WO_STATUS.get(w.get("id_status_work_order"), "Em andamento"),
                        "responsavel": str(w.get("personnel_description") or "").strip(),   # p/ herdar na OS filha (deep link)
                        "id_item": w.get("id_item"),   # id do ATIVO da OS — o histórico de ETM resolve por ele quando o code não segue o padrão ESTM (caso TCN100, 26/08)
                        "_ts": str(w.get("creation_date") or "")})
                if not any((l or {}).get("id") == FRAC_OS_PERF_LABEL for l in (w.get("labels") or [])):
                    continue
                if not g:
                    continue
                idx.setdefault(g, []).append({
                    "os": w.get("wo_folio"), "categoria": "Performance",
                    "status": FRAC_WO_STATUS.get(w.get("id_status_work_order"), "Em andamento"),
                    "nota": str(w.get("description") or "").strip(),
                    "sub": (str(w.get("items_log_description") or "").split("{")[0].strip() or None),
                    "data": str(w.get("creation_date") or "")[:10],
                    "aberta": True, "_ts": str(w.get("creation_date") or "")})
            total = d.get("total") if isinstance(d, dict) else None
            start += len(rows)
            if total and start >= total:
                break
    except Exception as e:
        print(f"[fracttal] sweep de OS de Performance falhou: {e}")
        return _frac_osperf_idx                    # mantém o índice anterior
    for g in idx:
        idx[g].sort(key=lambda o: o.get("_ts") or "", reverse=True)
        for o in idx[g]:
            o.pop("_ts", None)
    for g in openidx:
        openidx[g].sort(key=lambda o: o.get("_ts") or "", reverse=True)
        seen, dd = set(), []                       # dedup por folio (uma OS pode ter vários itens)
        for o in openidx[g]:
            o.pop("_ts", None)
            if o.get("folio") in seen:
                continue
            seen.add(o.get("folio")); dd.append(o)
        openidx[g] = dd
    # backfill: atribuições SEM responsável (feitas antes desse campo) pegam do índice — folio é único global
    try:
        folio_resp = {str(o.get("folio")): o.get("responsavel", "")
                      for lst in openidx.values() for o in lst if o.get("responsavel")}
        if folio_resp:
            with _state_lock:
                d = _load_state(); mud = False
                for v in d.get("os_atribuidas", {}).values():
                    if isinstance(v, dict) and not v.get("responsavel") and folio_resp.get(str(v.get("folio"))):
                        v["responsavel"] = folio_resp[str(v["folio"])]; mud = True
                if mud:
                    _save_state(d)
    except Exception as e:
        print(f"[fracttal] backfill responsável das atribuições falhou: {e}")
    # VARREDURA VAZIA NÃO SOBRESCREVE ÍNDICE BOM (mesma proteção que o SunOp e a API PV já têm).
    # O caminho de exceção acima já devolve o anterior, mas uma varredura que SUCEDE e volta sem
    # linhas (primeiro lote vazio → break, sem erro) caía aqui e gravava {"idx":{},"openwo":{}} —
    # é exatamente o frac_osperf_index.json de ~51 bytes. Aí o selo de OS some da tela e o boot
    # frio lê o arquivo vazio. Só recusa quando JÁ havia índice: primeira carga legítima passa.
    if not idx and not openidx and (_frac_osperf_idx or _frac_openwo_idx):
        print("[fracttal] sweep de OS voltou VAZIO e havia índice bom — mantido o anterior "
              "(arquivo não sobrescrito)")
        return _frac_osperf_idx
    _frac_osperf_idx, _frac_osperf_ts, _frac_openwo_idx = idx, time.time(), openidx
    try:
        with open(_FRAC_OSPERF_FILE, "w", encoding="utf-8") as f:
            json.dump({"ts": _frac_osperf_ts, "idx": idx, "openwo": openidx}, f, ensure_ascii=False)
    except Exception as e:
        print(f"[fracttal] não salvou o índice de OS de Performance: {e}")
    return _frac_osperf_idx


def _os_perf_de(usina):
    """OSs de Performance EM ABERTO da usina, do FRACTTAL (etiqueta PERFORMANCE), casando o supervisório →
    'Usina Fractall' (BD_Performance/Equipamentos). → (lista, Usina Fractall). Substitui a planilha de Tickets."""
    if not FRACTTAL_ON:
        return [], None
    fr = _frac_fractall_map().get(str(usina or "").strip().lower())
    if not fr:
        return [], None
    return list(_frac_osperf_index().get(_frac_grpkey(fr), [])), fr


def _frac_open_de(usina):
    """TODAS as OS abertas (id_status=1) da usina, do FRACTTAL, casando o nome → 'Usina Fractall'. →
    (lista com colunas do pick-list, Usina Fractall). Alimenta o modal do botão 'Atribuir OS'."""
    if not FRACTTAL_ON:
        return [], None
    fr = _frac_fractall_map().get(str(usina or "").strip().lower())
    if not fr:
        return [], None
    _frac_osperf_index()                       # garante o sweep (popula _frac_openwo_idx junto)
    return list(_frac_openwo_idx.get(_frac_grpkey(fr), [])), fr


# ── OS de ESTAÇÃO METEOROLÓGICA (pedido Levi 26/08: destaque no card + histórico + abrir OS) ────
# "Estação meteorológica ou qualquer um desse grupo": o Fracttal cadastra a estação e às vezes os
# sensores como ativos separados ("Piranômetro 1" na MAB100/JCD100). O filtro é pelo NOME DO ATIVO
# da OS (campo `ativo` do índice openwo), nunca pela descrição — "[ETM] - Coleta" na desc de uma OS
# de outro ativo não pode acender o card.
_FRAC_ETM_RX = re.compile(
    r"meteorol|esta[cç][aã]o\s+meteo|piran[oô]metro|pluvi[oô]metro|datalogger|\betm\b", re.I)


def _frac_eh_etm(nome_ativo) -> bool:
    """O ativo pertence ao grupo estação meteorológica?"""
    return bool(_FRAC_ETM_RX.search(str(nome_ativo or "")))


def _frac_key_semuf(s):
    """Chave de casamento SEM o sufixo de UF. O BD e o Fracttal divergem no estado da mesma
    usina — caso real 26/08: BD 'Axis - Ponto Belo 1 - PE' × Fracttal 'axis - ponto belo 1 - ba'
    (a usina fica no ES; os dois lados estão errados de UFs diferentes). Casar com a UF dentro
    perde a usina inteira; sem ela, o prefixo cliente+usina+número segura a unicidade."""
    return re.sub(r"\s*-\s*[a-z]{2}$", "", _frac_grpkey(s))


def _frac_openwo_fresco():
    """Índice de OS abertas SEM risco de sweep inline no processo web.

    O `_frac_osperf_index()` refaz a varredura (~19 requests à Fracttal) quando o TTL de 30 min
    vence — no worker tudo bem (é o loop dele), mas no WEB isso entraria no caminho de uma
    requisição de tela. Como o worker regrava o ARQUIVO a cada varredura, aqui basta reler o
    arquivo quando o mtime mudar: o web fica fresco de graça e nunca varre."""
    global _frac_osperf_idx, _frac_osperf_ts, _frac_openwo_idx
    try:
        m = os.path.getmtime(_FRAC_OSPERF_FILE)
        if m != _frac_openwo_fresco._mtime:
            with open(_FRAC_OSPERF_FILE, encoding="utf-8") as f:
                d = json.load(f)
            if d.get("openwo") or d.get("idx"):     # arquivo vazio não apaga índice bom
                _frac_openwo_idx = d.get("openwo") or {}
                _frac_osperf_idx = d.get("idx") or {}
                _frac_osperf_ts = d.get("ts") or time.time()
            _frac_openwo_fresco._mtime = m
    except Exception:
        pass
    if not _frac_openwo_idx and FRACTTAL_ON:
        _frac_osperf_index()                       # sem arquivo nenhum (1ª vida): varre uma vez
    return _frac_openwo_idx


_frac_openwo_fresco._mtime = 0.0


@app.route("/api/etm/os", methods=["POST"])
def api_etm_os():
    """OS ABERTAS do grupo estação meteorológica, por usina — alimenta o destaque laranja e o
    pulso dos cards do ETM. Body: {usinas: [nomes de exibição]}.
    → {ok, por_usina: {nome: {cadastrada, os: [{folio, ativo, desc, criada, status}]}}}
    `cadastrada: false` = usina sem 'Usina Fractall' no BD (as ~14 da Thopen) — o front esconde
    chip/botão/histórico em vez de oferecer ação que não tem onde chegar."""
    if not FRACTTAL_ON:
        return jsonify({"ok": False, "sem_credencial": True})
    body = flask_request.get_json(silent=True) or {}
    usinas = [str(u).strip() for u in (body.get("usinas") or []) if str(u).strip()][:200]
    mapa = _frac_fractall_map()
    ow = _frac_openwo_fresco()
    ow_semuf = {}
    for k, v in ow.items():                        # índice tolerante (ver _frac_key_semuf)
        ow_semuf.setdefault(_frac_key_semuf(k), []).extend(v)
    por_usina = {}
    for u in usinas:
        fr = mapa.get(u.lower())
        if not fr:
            por_usina[u] = {"cadastrada": False, "os": []}
            continue
        bruto = ow.get(_frac_grpkey(fr))
        if bruto is None:
            bruto = ow_semuf.get(_frac_key_semuf(fr), [])
        lst = [o for o in bruto if _frac_eh_etm(o.get("ativo"))]
        por_usina[u] = {"cadastrada": True, "os": [
            {"folio": o.get("folio"), "ativo": o.get("ativo"), "desc": o.get("desc"),
             "criada": o.get("criada"), "status": o.get("status")} for o in lst]}
    return jsonify({"ok": True, "por_usina": por_usina})


@app.route("/api/etm/grupos")
def api_etm_grupos():
    """Mapa {nome do card (normalizado) → usina física} da aba Equipamentos — a régua de
    AGRUPAMENTO dos cards de ETM (pedido Levi 27/08: "agrupe de acordo com a nomenclatura da aba
    Equipamentos"). O cadastro manda; heurística de nome no front é só fallback p/ usina fora dele.
    Chaveado pelo supervisório (o nome que a API PV põe no card), pelo supervisório sem o "(id)"
    e pelo display — cobre card traduzido e card cru (os 104 displays ambíguos ficam no cru)."""
    def _k(s):
        return re.sub(r"\s+", " ", str(s or "")).strip().lower()
    g = {}
    for sup, grupo in USINA_GRUPO.items():
        grupo = str(grupo or "").strip()
        if not grupo:
            continue
        g[_k(sup)] = grupo
        g[_k(re.sub(r"\s*\(\d+\)\s*$", "", str(sup)))] = grupo
        disp = USINA_DISPLAY.get(sup)
        if disp:
            g[_k(disp)] = grupo
    return jsonify({"ok": True, "grupos": g})


def _frac_etm_ativos(usina):
    """Ativos de estação meteorológica da usina no Fracttal: [{id, desc}].
    O code segue o MESMO padrão do inversor ({BASE}-INVR{N.M}): estação = {BASE}-ESTM{n}.
    Verificado em 26/08 nas 4 carteiras (PTB100/CPP100/MAB100/TIM100-ESTM1, todos resolvem;
    ESTM2 tenta só se a 1 existir — usina com duas estações). `_frac_ativo` cacheia 12h,
    inclusive o None (não martela a Fracttal com code inexistente)."""
    base = _frac_codebase(usina)
    if not base:
        # nome → 'Usina Fractall' (BD) → índice de code-base, tolerante à UF divergente
        desc = _frac_fractall_map().get(str(usina or "").strip().lower())
        if desc:
            alvo = _frac_key_semuf(desc)
            for k, ent in _frac_codebase_index().items():
                if _frac_key_semuf(k) == alvo:
                    base = ent.get("cb")
                    break
    out = []
    if base:
        for n in (1, 2):
            a = _frac_ativo(f"{base}-ESTM{n}")
            if a:
                out.append(a)
            elif n == 1:
                break
    if not out:
        # Nem toda carteira segue o padrão {BASE}-ESTM{n} (TCN100/Tucano não tem, 26/08). Plano B:
        # as OS ABERTAS do grupo ETM da usina carregam o `id_item` do ativo — resolve por elas.
        # Só funciona enquanto houver OS aberta, então o resultado fica em cache de memória para
        # o histórico continuar acessível depois que a OS fechar (até o restart).
        fr = _frac_fractall_map().get(str(usina or "").strip().lower())
        if fr:
            ow = _frac_openwo_fresco()
            bruto = ow.get(_frac_grpkey(fr))
            if bruto is None:
                alvo = _frac_key_semuf(fr)
                bruto = [o for k, lst in ow.items() if _frac_key_semuf(k) == alvo for o in lst]
            vistos = set()
            for o in bruto or []:
                if _frac_eh_etm(o.get("ativo")) and o.get("id_item") and o["id_item"] not in vistos:
                    vistos.add(o["id_item"])
                    out.append({"id": o["id_item"], "desc": str(o.get("ativo") or "")})
    ck = str(usina or "").strip().lower()
    if out:
        _frac_etm_ativos._cache[ck] = out
    return out or _frac_etm_ativos._cache.get(ck, [])


_frac_etm_ativos._cache = {}


@app.route("/api/etm/os/historico")
def api_etm_os_historico():
    """Histórico de OSs da estação meteorológica da usina, 10 por página (pedido Levi 26/08).
    ?usina=<nome de exibição>&offset=0 → {ok, total, offset, os: [...]} — abertas E concluídas,
    mais recentes primeiro. A busca real (_frac_os_de) traz até 200 dedupadas e fica cacheada
    FRAC_OS_TTL; a paginação é local, então trocar de página não custa chamada à Fracttal."""
    if not FRACTTAL_ON:
        return jsonify({"ok": False, "sem_credencial": True})
    usina = (flask_request.args.get("usina") or "").strip()
    try:
        offset = max(0, int(flask_request.args.get("offset") or 0))
    except Exception:
        offset = 0
    ativos = _frac_etm_ativos(usina)
    if not ativos:
        return jsonify({"ok": True, "usina": usina, "sem_ativo": True, "total": 0, "offset": 0, "os": []})
    todas = []
    for a in ativos:
        todas.extend(_frac_os_de(a["id"], n=200))
    seen = set()
    lst = []
    for o in sorted(todas, key=lambda o: str(o.get("criada") or ""), reverse=True):
        if o.get("folio") in seen:
            continue
        seen.add(o.get("folio"))
        # CANCELADA fica fora do histórico (pedido Levi 26/08) — pelo TEXTO do status, não pelo
        # id, para o filtro não quebrar em silêncio se o FRAC_WO_STATUS ganhar variação de nome.
        if "cancelad" in str(o.get("status") or "").lower():
            continue
        lst.append(o)
    return jsonify({"ok": True, "usina": usina, "total": len(lst), "offset": offset,
                    "os": lst[offset:offset + 10]})


def _frac_osperf_loop():
    """Prewarm no boot + refresh a cada 30 min (o índice de OS de Performance fica quente p/ o selo/modal)."""
    while True:
        try:
            if FRACTTAL_ON:
                _frac_osperf_index(force=True)
        except Exception as e:
            print(f"[fracttal] loop OS Performance: {e}")
        time.sleep(FRAC_OSPERF_TTL)


# ── Disponibilidade por OS do Fracttal × BD (aba do Gerencial) ───────────────────────────────
# Réguas fechadas com o Levi em 25-26/08/26 (análise "Disponibilidade Fracttal x BD"): o cálculo
# mora em disponibilidade.py (módulo PURO, testado em tests/test_disp_fracttal.py) — aqui é só
# varredura, cache e rotas. O WORKER varre e calcula (30 min, padrão do _frac_osperf_loop) e
# publica em frac_disp_index.json; o WEB relê o arquivo por mtime e serve — NUNCA calcula.
import disponibilidade as _disp_mod

_FRAC_DISP_FILE = os.path.join(_AQUI, "frac_disp_index.json")
FRAC_DISP_TTL = 30 * 60
FRAC_DISP_MARGEM_D = 45          # OS criada até 45d antes do mês anterior ainda entra na varredura
_frac_disp_mem = {"mtime": 0.0, "dados": {}}
_DISP_CAMPOS_TASK = ("tasks_log_task_type_main", "id_status_work_order", "event_date",
                     "date_maintenance", "final_date", "wo_final_date", "code",
                     "items_log_description", "groups_1_description", "description",
                     "created_by", "personnel_description", "user_assigned")

_disp_equip_cache = {"ts": 0.0, "linhas": []}


def _disp_equip_linhas():
    """Aba Equipamentos (espelho bases/) → lista de dicts p/ o módulo de disponibilidade.
    Cacheado como o _frac_fractall_map: estrutura de usina muda raramente."""
    if _disp_equip_cache["linhas"] and (time.time() - _disp_equip_cache["ts"]) < FRAC_CODE_TTL:
        return _disp_equip_cache["linhas"]
    linhas = []
    try:
        df = pd.read_excel(_bd_readable_path(), sheet_name="Equipamentos", header=2)
        for _, r in df.iterrows():
            pot = r.get("Potência (kWp)")
            linhas.append({
                "cliente": r.get("Cliente"), "usina": r.get("Usina"),
                "usina_fracttal": r.get("Usina Fractall"), "equipamento": r.get("Equipamento"),
                "parente": r.get("Equipamento Parente"),
                "pot_kwp": float(pot) if pd.notna(pot) else None,
                "n_inv": r.get("N de Inversores") if pd.notna(r.get("N de Inversores")) else None,
                "full_om": r.get("Full O&M"),
            })
    except Exception as e:
        print(f"[disp] aba Equipamentos falhou: {e}")
    if linhas:
        _disp_equip_cache.update(ts=time.time(), linhas=linhas)
    return _disp_equip_cache["linhas"]


def _disp_meses_alvo(hoje=None):
    """[(rótulo 'YYYY-MM', per_ini, per_fim)] do mês corrente (até D-1) e do anterior (cheio).
    per_fim é EXCLUSIVO. No dia 1 o mês corrente não tem dia fechado — vai vazio de propósito."""
    hoje = hoje or datetime.now()
    ini_cor = datetime(hoje.year, hoje.month, 1)
    fim_cor = datetime(hoje.year, hoje.month, hoje.day)          # D-1 fechado (exclusivo)
    ini_ant = (ini_cor - timedelta(days=1)).replace(day=1)
    return [(f"{ini_cor:%Y-%m}", ini_cor, fim_cor), (f"{ini_ant:%Y-%m}", ini_ant, ini_cor)]


def _frac_disp_sweep(limite_dt):
    """Varre work_orders (DESC por criação) até criação < limite → {folio: [tasks reduzidas]}.
    ~140 páginas p/ 2 meses + margem; roda SÓ no worker, a cada FRAC_DISP_TTL."""
    wos, start = {}, 0
    limite = limite_dt.strftime("%Y-%m-%d")
    while start < 40000:
        d = _frac_get("work_orders/", start=start, limit=200)
        rows = (d.get("data") if isinstance(d, dict) else d) or []
        if not rows:
            break
        ultima = ""
        for w in rows:
            ultima = str(w.get("creation_date") or "")[:10]
            fol = w.get("wo_folio")
            if fol is not None:
                wos.setdefault(str(fol), []).append({k: w.get(k) for k in _DISP_CAMPOS_TASK})
        start += len(rows)
        if ultima and ultima < limite:
            break
    return wos


def _frac_disp_recalcular():
    """WORKER: varre + calcula os 2 meses + persiste (atômico). Varredura vazia não sobrescreve
    índice bom (mesma proteção do _frac_osperf_index)."""
    if not FRACTTAL_ON:
        return
    meses = _disp_meses_alvo()
    limite = min(m[1] for m in meses) - timedelta(days=FRAC_DISP_MARGEM_D)
    wos = _frac_disp_sweep(limite)
    if not wos:
        print("[disp] varredura do Fracttal voltou VAZIA — índice anterior mantido")
        return
    equip = _disp_equip_linhas()
    if not equip:
        print("[disp] sem aba Equipamentos — índice não recalculado")
        return
    dados = {"ts": time.time(), "meses": {}}
    for rot, ini, fim in meses:
        try:
            dados["meses"][rot] = _disp_mod.calcular(wos, equip, ini, fim)
        except Exception as e:
            print(f"[disp] cálculo de {rot} falhou: {e}")
    if not dados["meses"]:
        return
    tmp = _FRAC_DISP_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(dados, f, ensure_ascii=False)
    os.replace(tmp, _FRAC_DISP_FILE)
    print(f"[disp] índice publicado ({', '.join(dados['meses'])}; {len(wos)} OSs varridas)")


def _frac_disp_dados():
    """WEB: lê o índice publicado pelo worker (relê o arquivo quando o mtime muda). Nunca calcula."""
    try:
        mt = os.path.getmtime(_FRAC_DISP_FILE)
    except OSError:
        return {}
    if mt > _frac_disp_mem["mtime"]:
        try:
            with open(_FRAC_DISP_FILE, encoding="utf-8") as f:
                _frac_disp_mem["dados"] = json.load(f)
            _frac_disp_mem["mtime"] = mt
        except Exception as e:
            print(f"[disp] leitura do índice falhou: {e}")
    return _frac_disp_mem["dados"] or {}


def _frac_disp_loop():
    """Prewarm no boot + refresh a cada 30 min (roda no worker, como os demais laços)."""
    while True:
        try:
            _frac_disp_recalcular()
        except Exception as e:
            print(f"[disp] loop: {e}")
        time.sleep(FRAC_DISP_TTL)


@app.route("/gerencial/disponibilidade")
def gerencial_disponibilidade():
    # Painel de disponibilidade por OS (design aprovado no mockup de 26/08). Consome a API abaixo.
    return render_template("disponibilidade.html")


@app.route("/api/gerencial/disponibilidade")
def api_gerencial_disponibilidade():
    """Payload pronto do mês (?mes=YYYY-MM; padrão = corrente). ?cliente=X filtra usinas/diário.
    Servido do índice do worker — se frio (boot recém-feito), devolve quente:false sem calcular."""
    dados = _frac_disp_dados()
    meses = dados.get("meses") or {}
    if not meses:
        return jsonify({"quente": False, "meses": []})
    mes = (flask_request.args.get("mes") or "").strip() or max(meses)
    p = meses.get(mes)
    if not p:
        return jsonify({"quente": False, "meses": sorted(meses)})
    cliente = (flask_request.args.get("cliente") or "").strip()
    if cliente:
        usinas = [u for u in p["usinas"] if (u.get("cliente") or "").strip().lower() == cliente.lower()]
        nomes = {u["usina"] for u in usinas}
        p = {**p, "usinas": usinas,
             "diario": {u: d for u, d in p["diario"].items() if u in nomes},
             "oss": [o for o in p["oss"] if set(o.get("usinas") or []) & nomes],
             "cenario_abertas": [c for c in p["cenario_abertas"] if set(c.get("usinas") or []) & nomes]}
    return jsonify({"quente": True, "mes": mes, "meses": sorted(meses),
                    "atualizado": dados.get("ts"), **p})


@app.route("/api/gerencial/disponibilidade/export")
def api_gerencial_disp_export():
    """Mapa diário usina × dia em Excel (?mes=&cliente=), no formato do painel: % com as
    mesmas faixas de cor. Workbook pequeno (≤140 linhas) — leve o bastante p/ o web."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    dados = _frac_disp_dados()
    meses = dados.get("meses") or {}
    mes = (flask_request.args.get("mes") or "").strip() or (max(meses) if meses else "")
    p = meses.get(mes)
    if not p:
        return jsonify({"erro": "índice de disponibilidade ainda não publicado"}), 503
    cliente = (flask_request.args.get("cliente") or "").strip()
    usinas = [u for u in p["usinas"]
              if not cliente or (u.get("cliente") or "").strip().lower() == cliente.lower()]
    n_dias = int(p["periodo"]["dias"])
    ano, mnum = mes.split("-")
    wb = Workbook()
    ws = wb.active
    ws.title = f"Mapa {mes}"
    NAVY, F_HDR = "161D30", Font(bold=True, color="FFFFFF", size=10)
    FILL_HDR = PatternFill("solid", fgColor=NAVY)

    def _cor_faixa(pct):
        # mesmas faixas da legenda do painel: 100 / ≥99 / 95-99 / 80-95 / 50-80 / <50
        if pct >= 99.95:
            return None
        if pct >= 99:
            return "D9EFC2"
        if pct >= 95:
            return "FCE8B8"
        if pct >= 80:
            return "F5C97E"
        if pct >= 50:
            return "F8CBCB"
        return "F2555A"

    ws.append(["Usina"] + [f"{d:02d}/{mnum}" for d in range(1, n_dias + 1)] + ["Mês"])
    for c in ws[1]:
        c.font, c.fill = F_HDR, FILL_HDR
        c.alignment = Alignment(horizontal="center")
    for u in sorted(usinas, key=lambda x: x["disp"] if x["disp"] is not None else 999):
        diario = p["diario"].get(u["usina"], {})
        row = [u["usina"]]
        for d in range(1, n_dias + 1):
            v = diario.get(f"{ano}-{mnum}-{d:02d}")
            row.append((v["disp"] if v else 100.0) / 100.0)
        row.append((u["disp"] or 0) / 100.0)
        ws.append(row)
        for j in range(2, n_dias + 3):
            cell = ws.cell(row=ws.max_row, column=j)
            cell.number_format = "0.0%"
            cor = _cor_faixa(cell.value * 100)
            if cor:
                cell.fill = PatternFill("solid", fgColor=cor)
                if cor == "F2555A":
                    cell.font = Font(color="FFFFFF", bold=True)
    ws.column_dimensions["A"].width = 24
    for j in range(2, n_dias + 3):
        ws.column_dimensions[get_column_letter(j)].width = 7.5
    ws.freeze_panes = "B2"
    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    nome = f"Disponibilidade_{cliente or 'parque'}_{mes}.xlsx".replace(" ", "_")
    return send_file(buf, as_attachment=True, download_name=nome,
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.route("/api/fracttal/inversor")
def api_fracttal_inversor():
    """Últimas OS da Fracttal de um inversor do dashboard. ?usina=CPP100&inv=Inversor 6.1[&n=5]"""
    if not FRACTTAL_ON:
        return jsonify({"ok": False, "sem_credencial": True})
    code = _frac_inv_code(flask_request.args.get("usina"), flask_request.args.get("inv"))
    if not code:
        return jsonify({"ok": False, "motivo": "inversor sem número reconhecível"})
    try:
        n = max(1, min(int(flask_request.args.get("n", 5)), 20))
    except (TypeError, ValueError):
        n = 5
    try:
        ativo = _frac_ativo(code)
        if not ativo:
            return jsonify({"ok": False, "motivo": "sem ativo correspondente na Fracttal", "code": code})
        return jsonify({"ok": True, "code": code, "ativo": ativo.get("desc"),
                        "os": _frac_os_de(ativo["id"], n)})
    except Exception as e:
        return jsonify({"ok": False, "erro": str(e)})


_frac_usina_cache = {}     # usina.lower -> {"ts", "abertas", "total"}


@app.route("/api/fracttal/usina")
def api_fracttal_usina():
    """OS ABERTAS no site da usina (badge no overview). ?usina=CPP100. Conta no nível do site
    (religamentos/verificações da usina); as OS por inversor aparecem no drill de cada um."""
    if not FRACTTAL_ON:
        return jsonify({"ok": False, "sem_credencial": True})
    usina = (flask_request.args.get("usina") or "").strip()
    key = usina.lower()
    ent = _frac_usina_cache.get(key)
    if ent and (time.time() - ent["ts"]) < FRAC_OS_TTL:
        return jsonify({"ok": True, "abertas": ent["abertas"], "total": ent["total"], "os": ent.get("os", [])})
    try:
        info = _frac_usina_ent(usina)
        site = info.get("site") if info else None
        if not site:
            return jsonify({"ok": False, "motivo": "sem site na Fracttal"})
        d = _frac_get("work_orders/", id_item=site, limit=200)
        rows = (d.get("data") if isinstance(d, dict) else d) or []
        folios = {}
        for w in rows:
            folios.setdefault(w.get("wo_folio"), w)
        ab = sorted((w for w in folios.values() if w.get("id_status_work_order") in (0, 1, 5, 6)),
                    key=lambda w: str(w.get("creation_date") or ""), reverse=True)
        os_ab = [{"folio": w.get("wo_folio"), "descricao": str(w.get("description") or "").strip(),
                  "status": FRAC_WO_STATUS.get(w.get("id_status_work_order"), "—"),
                  "criada": str(w.get("creation_date") or "")[:10]} for w in ab]
        res = {"abertas": len(os_ab), "total": len(folios), "os": os_ab}
        _frac_usina_cache[key] = {"ts": time.time(), **res}
        return jsonify({"ok": True, **res})
    except Exception as e:
        return jsonify({"ok": False, "erro": str(e)})


# ── OS por tipo (corretiva/emergencial/inspeção/religamento[/remoto]) — usina + inversor/cabine ──
FRAC_TIPOS_ALVO = {"corretiva", "corretiva emergencial", "inspeção", "inspecao",
                   "religamento", "religamento remoto"}
_frac_wos_cache = {}     # id_item -> {ts, rows(brutas)}


def _frac_wos_raw(id_item):
    """WOs BRUTAS de um ativo (com tasks_log_task_type_main + creation_date), cacheado FRAC_OS_TTL."""
    ent = _frac_wos_cache.get(id_item)
    if ent and (time.time() - ent["ts"]) < FRAC_OS_TTL:
        return ent["rows"]
    d = _frac_get("work_orders/", id_item=id_item, limit=200)
    rows = (d.get("data") if isinstance(d, dict) else d) or []
    _frac_wos_cache[id_item] = {"ts": time.time(), "rows": rows}
    return rows


def _frac_ativo_curto(ild: str) -> str:
    """Extrai o nome curto do ativo do `items_log_description`. Padrão Fracttal:
    OS de SITE  : 'Thopen - Caxambu 1 - SP  Caxambu São Paulo Brasil { THPN-CXB100 }' → 'Caxambu 1'
    OS de INV   : 'Inversor 2.2 Huawei SUN2000-250KTL-H1   { CPP100-INVR2.2 }' → 'Inversor 2.2'"""
    s = (ild or "").strip()
    if not s:
        return ""
    base = re.sub(r"\s*\{[^}]*\}\s*$", "", s).strip()    # tira " { CODE }"
    nome = re.split(r"\s{2,}", base, maxsplit=1)[0].strip()   # 1º bloco antes do endereço
    m = re.match(r"(Inversor\s+[\d.]+)", nome)
    if m:
        return m.group(1)
    # Descarta segmento de endereço/UF: começa com UF de 2 letras + espaço (ex.: "GO Rodovia BR 040…")
    # ou é só a UF. Isso pega: 'Thopen - Caxambu 1 - SP' → 'Caxambu 1';
    # 'Thopen - Sítio dos Nogueiras 1 - GO Rodovia BR 040…' → 'Sítio dos Nogueiras 1'.
    parts = [p.strip() for p in nome.split(" - ") if p.strip()]
    util = [p for p in parts if not re.match(r"^[A-Z]{2}(\s|$)", p)]
    if util:
        return util[-1]
    if parts:
        return parts[-1]
    return nome[:60]


FRAC_TZ_OFF_H = -3      # America/Sao_Paulo — o Fracttal devolve as datas em UTC (…+00:00)


def _frac_dt_local(s):
    """Data/hora do Fracttal (ISO com offset, na prática UTC) convertida pro fuso LOCAL. O `_dt_iso`
    corta em [:19] e PERDE o offset — sem isto uma queda às 22:02Z (19:02 daqui) entraria como 22:02 e
    a janela solar 06–18h sairia errada. Sem offset na string, assume que já veio local."""
    d = _dt_iso(s)
    if d is None:
        return None
    txt = str(s).strip()
    m = re.search(r"([+-])(\d{2}):?(\d{2})$", txt)
    if m:
        off = (int(m.group(2)) * 60 + int(m.group(3))) * (1 if m.group(1) == "+" else -1)
        d -= timedelta(minutes=off)                    # → UTC
    elif not txt.endswith("Z"):
        return d                                       # sem fuso declarado: trata como local
    return d + timedelta(hours=FRAC_TZ_OFF_H)          # UTC → local


def _frac_os_filtradas(id_item, mes=None):
    """OSs do ativo nos 5 tipos-alvo (por tasks_log_task_type_main). Mostra: (a) toda OS NÃO encerrada
    (aberta), independentemente da data; (b) as concluídas do mês YYYY-MM pedido. NUNCA mostra
    Canceladas (status 4). Dedup por folio (uma OS pode ter várias tarefas). Abertas em 1º lugar."""
    seen = {}
    for w in _frac_wos_raw(id_item):
        tipo = str(w.get("tasks_log_task_type_main") or "").strip()
        if tipo.lower() not in FRAC_TIPOS_ALVO:
            continue
        st = w.get("id_status_work_order")
        if st == 4:                                  # Cancelada → nunca mostra
            continue
        aberta = st in (0, 1, 5, 6)                  # não encerrada
        cri = str(w.get("creation_date") or "")
        if not aberta and mes and cri[:7] != mes:    # concluída fora do mês → fora
            continue
        fol = w.get("wo_folio")
        if fol in seen:
            continue
        # data/hora do EVENTO (quando o problema aconteceu) — é ela que casa com o dia do PR — e o FIM
        # da OS. LOCAL, não UTC: o dia do ▲ no gráfico depende disso (queda 01:30Z é do dia anterior aqui).
        _i0 = _frac_dt_local(w.get("event_date") or w.get("date_maintenance"))
        _f0 = _frac_dt_local(w.get("final_date") or w.get("wo_final_date"))
        _ev  = _i0.strftime("%Y-%m-%d") if _i0 else ""
        _fim = _f0.strftime("%Y-%m-%d") if _f0 else ""
        # DURAÇÃO em HORAS SOLARES (06–18h): fora dessa janela a usina não geraria mesmo, então parada
        # noturna não vira "1 dia parado". OS aberta conta até agora. Também mando os dias (bruto).
        _dias = None
        try:
            _d0 = datetime.strptime(_ev or cri[:10], "%Y-%m-%d")
            _d1 = datetime.strptime(_fim, "%Y-%m-%d") if _fim else datetime.now()
            _dias = max(0, (_d1.date() - _d0.date()).days)
        except Exception:
            pass
        _hs = _horas_solares(_i0, _f0 or datetime.now()) if _i0 else None
        seen[fol] = {"folio": fol, "tipo": tipo, "descricao": str(w.get("description") or "").strip(),
                     "ativo": _frac_ativo_curto(w.get("items_log_description") or ""),
                     "status": FRAC_WO_STATUS.get(st, "—"), "aberta": aberta, "criada": cri[:10],
                     "evento": _ev, "fim": _fim, "dias": _dias,
                     "horas_solares": _hs, "horas_fmt": _fmt_hsolar(_hs),
                     # ISO LOCAL (sem fuso) — o front usa p/ ratear a perda por dia dentro da janela solar
                     "evento_ts": _i0.strftime("%Y-%m-%dT%H:%M:%S") if _i0 else "",
                     "fim_ts": _f0.strftime("%Y-%m-%dT%H:%M:%S") if _f0 else ""}
    # abertas primeiro, depois por data (mais recente no topo)
    return sorted(seen.values(), key=lambda x: (x["aberta"], x["criada"]), reverse=True)


@app.route("/api/fracttal/os", methods=["POST"])
def api_fracttal_os():
    """OSs (5 tipos) de uma usina no mês — nível usina (site) + por inversor (com cabine).
    Body JSON: {usina, mes:'YYYY-MM'|None, inversores:[nomes display 'Inversor N.M']}."""
    if not FRACTTAL_ON:
        return jsonify({"ok": False, "sem_credencial": True})
    body = flask_request.get_json(silent=True) or {}
    usina = (body.get("usina") or "").strip()
    mes = (body.get("mes") or "").strip() or None
    invs = body.get("inversores") or []
    out = {"ok": True, "usina": usina, "mes": mes, "usina_os": [], "por_inversor": {}}
    try:
        ent = _frac_usina_ent(usina)
        if ent and ent.get("site"):
            out["usina_os"] = _frac_os_filtradas(ent["site"], mes)
    except Exception as e:
        out["erro_site"] = str(e)
    for nome in invs:
        try:
            code = _frac_inv_code(usina, nome)
            ativo = _frac_ativo(code) if code else None
            if not ativo:
                continue
            m = re.search(r"(\d+)\.(\d+)", str(nome))
            out["por_inversor"][nome] = {
                "cabine": int(m.group(1)) if m else None,
                "inv": int(m.group(2)) if m else None,
                "code": code, "os": _frac_os_filtradas(ativo["id"], mes)}
        except Exception:
            continue
    tot = len(out["usina_os"]) + sum(len(v["os"]) for v in out["por_inversor"].values())
    out["total"] = tot
    return jsonify(out)


# ══ RONDA AUTOMÁTICA VIA WHATSAPP — 5 grupos (1 por região), 2 envios/dia ════════════════════════
# Serviço Node local (C:\GridcoWhats\wa_service.js, whatsapp-web.js) segura a sessão do CHIP
# DEDICADO e expõe /send em 127.0.0.1:5099. Config: whats_ronda.json {"enabled", "service_url",
# "token", "horarios": ["07:30","15:30"], "grupos": {"Norte": "1203...@g.us", ...}}.
# Texto = MESMO formato do modal da ronda (rondaTexto/_rondaUsinas do index.html), gerado aqui.
_WHATS_CFG_PATH = os.path.join(_AQUI, "whats_ronda.json")
_WHATS_SENT_PATH = os.path.join(_AQUI, "whats_enviados.json")


def _whats_sent_load():
    """Estado de envio da ronda PERSISTIDO em disco: {"YYYY-MM-DD|HH:MM": ["Norte","Sul",...]} =
    regiões já enviadas COM SUCESSO naquele slot. Em disco → sobrevive a restart do servidor (antes
    era só na memória, então um reinício no meio da janela reenviava TUDO). Mantém só o dia de hoje."""
    try:
        with open(_WHATS_SENT_PATH, encoding="utf-8") as f:
            d = json.load(f) or {}
    except Exception:
        d = {}
    hoje = datetime.now().strftime("%Y-%m-%d")
    return {k: list(v) for k, v in d.items() if str(k).startswith(hoje) and isinstance(v, list)}


def _whats_sent_save(d):
    try:
        hoje = datetime.now().strftime("%Y-%m-%d")
        d = {k: sorted(set(v)) for k, v in d.items() if str(k).startswith(hoje)}
        tmp = _WHATS_SENT_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
        _replace_atomico(tmp, _WHATS_SENT_PATH)   # atômico: um 2º processo relendo nunca vê JSON pela metade
    except Exception as e:
        print(f"[ronda-whats] não gravei whats_enviados.json: {e}")


# {key: [regiões enviadas com sucesso]} — carregado do disco no boot (retoma o dia sem reenviar)
_whats_state = {"enviados": _whats_sent_load()}


def _whats_cfg():
    try:
        with open(_WHATS_CFG_PATH, encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception:
        return {}


def _ronda_ang(v):
    return f"{round(v)}°" if isinstance(v, (int, float)) else "—"


_TRK_GARANTIA_PATH  = os.path.join(_AQUI, "trackers_garantia.json")
# Override LOCAL (fora do git): export do SharePoint regerado NESTA máquina. Existindo, SUBSTITUI o
# versionado — assim dá p/ atualizar a garantia sem que o `git pull` brigue com o arquivo vivo, e o
# clone novo continua nascendo com a referência curada do repositório.
_TRK_GARANTIA_LOCAL = os.path.join(_AQUI, "trackers_garantia.local.json")


def _trk_id_num(s):
    """MAIOR inteiro no identificador do tracker → chave de comparação p/ o de-para planilha↔plataforma
    (os nomes divergem: 'T06'→6, 'Tracker 06'→6, 'TR 1.16'→16, 'T02-MDG1'→2, 'MDG4 T33'→33)."""
    ns = re.findall(r"\d+", str(s))
    return max(int(x) for x in ns) if ns else None


def _trk_garantia_map():
    """{usina_substring_nrm: set(números de tracker)} da planilha de Gestão de Chamados (status !=
    Concluído), de trackers_garantia.json — ou do .local.json, que tem precedência. Ausente/vazio =
    no-op (a ronda segue igual). Cacheado por mtime p/ reler quando o arquivo mudar sem reiniciar."""
    path = next((p for p in (_TRK_GARANTIA_LOCAL, _TRK_GARANTIA_PATH) if os.path.exists(p)), None)
    if not path:
        return {}
    try:
        mt = os.path.getmtime(path)
    except OSError:
        return {}
    c = _trk_garantia_map._c
    if c and c[0] == (path, mt):
        return c[1]
    out = {}
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f) or {}
        for usina, info in (data.get("usinas") or {}).items():
            ids = info.get("trackers") if isinstance(info, dict) else info
            nums = {_trk_id_num(t) for t in (ids or [])}
            nums.discard(None)
            if nums:
                out[_nrm(usina)] = nums
    except Exception as e:
        print(f"[ronda-whats] {os.path.basename(path)} inválido: {e}")
        return {}
    _trk_garantia_map._c = ((path, mt), out)
    return out


_trk_garantia_map._c = None


# ── Histórico de parados p/ RECORRÊNCIA (Levi 23/07) — grava um snapshot dos trackers parados a cada
#    coleta FORÇADA da ronda; "recorrente" = tracker parado em vários DIAS. Fonte = a própria detecção
#    da plataforma (5 fontes solares), NÃO os grupos (leitura quebrada) nem a planilha (que atrasa ~2sem).
_TRK_HIST_PATH = os.path.join(_AQUI, "trackers_parados_hist.jsonl")


def _trk_parados_snapshot(rows, falhas, dedup_min=45, keep_dias=45):
    """Anexa 1 linha JSON por coleta: {ts, n, falhas, parados:[{u,t,r,sc,g}]}. Dedup pelo ts do ÚLTIMO
    snapshot no arquivo (pula se < dedup_min → não infla com refresh de dashboard/preview repetido).
    Poda linhas mais velhas que keep_dias. Escrita atômica (temp+replace)."""
    agora = datetime.now()
    linhas = []
    try:
        with open(_TRK_HIST_PATH, encoding="utf-8") as f:
            linhas = f.readlines()
    except FileNotFoundError:
        pass
    except Exception as e:
        print(f"[recorrentes] leitura do hist falhou: {e}"); linhas = []
    if linhas:                                        # dedup pelo último ts gravado (robusto a restart)
        try:
            ult = json.loads(linhas[-1]).get("ts", "")
            if (agora - datetime.strptime(ult, "%Y-%m-%d %H:%M")).total_seconds() < dedup_min * 60:
                return
        except Exception:
            pass
    snap = {"ts": agora.strftime("%Y-%m-%d %H:%M"), "n": len(rows), "falhas": list(falhas or []),
            "parados": [{"u": r.get("usina"), "t": str(r.get("tracker")), "r": r.get("regiao"),
                         "sc": bool(r.get("sem_comunicacao")), "g": bool(r.get("em_garantia"))}
                        for r in rows if r.get("tracker") not in (None, "")]}
    linhas.append(json.dumps(snap, ensure_ascii=False) + "\n")
    corte = agora - timedelta(days=keep_dias)
    def _recente(ln):
        try:
            return datetime.strptime(json.loads(ln).get("ts", ""), "%Y-%m-%d %H:%M") >= corte
        except Exception:
            return True
    linhas = [ln for ln in linhas if _recente(ln)]
    try:
        with open(_TRK_HIST_PATH + ".tmp", "w", encoding="utf-8") as f:
            f.writelines(linhas)
        _replace_atomico(_TRK_HIST_PATH + ".tmp", _TRK_HIST_PATH)
    except Exception as e:
        print(f"[recorrentes] gravação do hist falhou: {e}")


def _trk_recorrentes(dias=14):
    """Recorrência do histórico: por (usina, tracker), em quantos DIAS distintos dos últimos `dias` o
    tracker apareceu parado, nº de aparições, região, e se está parado no snapshot MAIS RECENTE
    ('parado agora'). Ordena por dias distintos desc, depois aparições."""
    try:
        with open(_TRK_HIST_PATH, encoding="utf-8") as f:
            raw = [json.loads(x) for x in f if x.strip()]
    except FileNotFoundError:
        raw = []
    except Exception as e:
        return {"erro": str(e)[:120], "snapshots": 0, "recorrentes": []}
    corte = datetime.now() - timedelta(days=dias)
    snaps = []
    for s in raw:
        try:
            t = datetime.strptime(s.get("ts", ""), "%Y-%m-%d %H:%M")
        except Exception:
            continue
        if t >= corte:
            snaps.append((t, s))
    snaps.sort(key=lambda x: x[0])
    agg, dias_set = {}, set()
    for t, s in snaps:
        dia = t.strftime("%Y-%m-%d"); dias_set.add(dia)
        for p in (s.get("parados") or []):
            u, trk = p.get("u"), str(p.get("t") or "")
            if not u or not trk:
                continue
            a = agg.setdefault((u, trk), {"usina": u, "tracker": trk, "regiao": p.get("r"),
                                          "dias": set(), "apar": 0, "sc": 0, "g": 0})
            a["dias"].add(dia); a["apar"] += 1
            if p.get("sc"): a["sc"] += 1
            if p.get("g"): a["g"] += 1
            if p.get("r"): a["regiao"] = p.get("r")
    ult = set()
    if snaps:
        ult = {(p.get("u"), str(p.get("t") or "")) for p in (snaps[-1][1].get("parados") or [])}
    rec = []
    for key, a in agg.items():
        rec.append({"usina": a["usina"], "tracker": a["tracker"], "regiao": a["regiao"] or "",
                    "dias": len(a["dias"]), "aparicoes": a["apar"],
                    "parado_agora": key in ult, "sem_com": a["sc"] > a["apar"] / 2,
                    "em_garantia": a["g"] > 0})
    rec.sort(key=lambda x: (-x["dias"], -x["aparicoes"], x["usina"]))
    return {"gerado": datetime.now().strftime("%d/%m/%Y %H:%M"), "janela_dias": dias,
            "snapshots": len(snaps), "dias_cobertos": len(dias_set),
            "primeiro": snaps[0][0].strftime("%d/%m %H:%M") if snaps else None,
            "ultimo": snaps[-1][0].strftime("%d/%m %H:%M") if snaps else None,
            "recorrentes": rec}


@app.route("/api/ronda/recorrentes")
def api_ronda_recorrentes():
    """Trackers recorrentes a partir do histórico dos parados da ronda. ?dias=14 (janela)."""
    try:
        dias = int(flask_request.args.get("dias") or 14)
    except Exception:
        dias = 14
    return jsonify(_trk_recorrentes(max(1, min(dias, 60))))


def _ronda_corta_onalvo(rows, dmin):
    """Tira da MENSAGEM da ronda os parados com |atual − alvo| ≤ dmin (Levi, caso Guatambu ago/26:
    42 trackers a ~1° do alvo poluíam a ronda — diferença pequena não é acionável pro campo).
    SEM COMUNICAÇÃO fica (não há ângulo confiável p/ comparar; esconder mascararia falha real), e
    linha sem atual/alvo numérico fica (não dá p/ julgar → não esconde). Só afeta o TEXTO da ronda:
    plataforma, snapshot e recorrência seguem com o conjunto completo. Trade-off aceito: travado no
    batente que COINCIDE com o alvo da manhã (TIM100-140, 30/07) some da ronda das 08:25 e aparece
    na das 13:00, quando o alvo já andou."""
    if not dmin or dmin <= 0:
        return rows
    out = []
    for r in rows:
        a, v = r.get("atual"), r.get("alvo")
        corta = (not r.get("sem_comunicacao")
                 and isinstance(a, (int, float)) and isinstance(v, (int, float))
                 and abs(a - v) <= dmin)
        if not corta:
            out.append(r)
    return out


def _ronda_parados_all(force=True):
    """Parados de TODAS as fontes em paralelo — MESMOS critérios da subaba 'Trackers parados
    (agora)' (as próprias funções _*_parados_rows) + lista de fontes que falharam. Marca em cada linha
    `em_garantia` (tracker já com chamado aberto na planilha de Gestão de Chamados) p/ a ronda separar."""
    partes, falhas = [], []
    with ThreadPoolExecutor(max_workers=5) as ex:
        futs = {ex.submit(_pv_parados_rows, force): "API PV",
                ex.submit(_pg_parados_rows, force): "Thopen",
                ex.submit(_sunop_parados_rows, "gridco", force): "Athon",
                ex.submit(_sunop_parados_rows, "axis", force): "Axis",
                ex.submit(_owen_parados_rows, force): "2C"}
        for f in as_completed(futs):
            try:
                partes.extend(f.result() or [])
            except Exception as e:
                falhas.append(futs[f])
                print(f"[ronda-whats] fonte {futs[f]} falhou: {e}")
    vistos, rows = set(), []
    for r in partes:
        k = (_nrm(r.get("usina") or ""), str(r.get("tracker")))
        if k not in vistos:
            vistos.add(k)
            rows.append(r)
    # CONJUNTO COMPLETO = exatamente o que a PLATAFORMA mostra (união deduplicada das mesmas
    # _*_parados_rows, MESMO critério status=="parado"), ANTES dos filtros que só valem pra MENSAGEM
    # da ronda (excluir_usinas + "em acompanhamento"). É ELE que alimenta a recorrência, p/ garantir
    # "parados da ronda == parados da plataforma" (Levi 23/07). O texto da ronda segue usando `rows`.
    _full_parados = list(rows)
    # Usinas EXCLUÍDAS da ronda (whats_ronda.json > "excluir_usinas"): casa por SUBSTRING no nome
    # normalizado — "Salto Pirapora" tira "Salto Pirapora 3" e qualquer unidade futura. Só afeta a
    # RONDA (o dashboard segue mostrando tudo). Reversível editando o JSON: o _whats_cfg relê a cada
    # disparo, sem precisar reiniciar o servidor.
    excl = [_nrm(x) for x in (_whats_cfg().get("excluir_usinas") or []) if str(x).strip()]
    if excl:
        rows = [r for r in rows if not any(e in _nrm(r.get("usina") or "") for e in excl)]
    # Corte "em cima do alvo" (knob "ronda_disp_min" no whats_ronda.json, graus; 0 desliga; padrão 10):
    try:
        _dmin = float(_whats_cfg().get("ronda_disp_min", 10))
    except Exception:
        _dmin = 10.0
    rows = _ronda_corta_onalvo(rows, _dmin)
    # Trackers já na planilha de Tickets como "Parado" com "Fim da ocorrência" VAZIO → JÁ acompanhados:
    # SOMEM da ronda (Levi 15/07). Casa usina (substring bidirecional, sem parênteses) + nº do tracker
    # (_trk_id_num — mesma régua da garantia). Reversível: some da exclusão quando a planilha ganha "Fim".
    pa = TICKETS_PARADO_ABERTO
    acomp = []                                     # excluídos por já estarem na planilha → "em acompanhamento da performance" (Levi 17/07)
    if pa:
        def _tick_aberto(r):
            un = _tk_norm(r.get("usina") or ""); tn = _trk_id_num(r.get("tracker"))
            return tn is not None and any((k in un or un in k) and tn in nums for k, nums in pa.items())
        keep = []
        for r in rows:
            (acomp if _tick_aberto(r) else keep).append(r)
        rows = keep
    # Trackers JÁ EM GARANTIA (chamado aberto, status != Concluído): marca a linha (não remove) p/ a
    # ronda separá-los numa seção "já em garantia". Casa por UFV (substring) + número do tracker.
    gar = _trk_garantia_map()
    for r in _full_parados:                            # marca no conjunto COMPLETO (rows é subconjunto, mesmos dicts)
        un = _nrm(r.get("usina") or ""); tn = _trk_id_num(r.get("tracker"))
        r["em_garantia"] = bool(tn is not None and any(k in un and tn in nums for k, nums in gar.items()))
    if force:                                          # snapshot p/ recorrência = CONJUNTO DA PLATAFORMA (não o filtrado)
        try:
            _trk_parados_snapshot(_full_parados, falhas)
        except Exception as e:
            print(f"[recorrentes] snapshot: {e}")
    return rows, falhas, acomp


_RONDA_CAUSA_CACHE = {"ts": 0.0, "data": None}


def _ronda_causa_map():
    """Causa dominante por usina do BOOK de campo (registros 'com causa citada' — vegetação/comunicação/
    motor…), p/ a ronda ANOTAR o parado com a causa já reportada. Best-effort (lê o WhatsApp; cache 5 min).
    Devolve {'cod': {código: causa}, 'key': {usina_key: causa}} ({} se o book falhar)."""
    now = time.time()
    c = _RONDA_CAUSA_CACHE
    if c["data"] is not None and (now - c["ts"]) < 300:
        return c["data"]
    out = {"cod": {}, "key": {}}
    try:
        agg = {}                                   # código -> {causa: n}
        for r in _ronda_book_cos().get("registros", []):
            if r.get("categoria") == "com_causa" and r.get("causa") and r.get("usina"):
                agg.setdefault(r["usina"], {})
                agg[r["usina"]][r["causa"]] = agg[r["usina"]].get(r["causa"], 0) + 1
        cod = {u: max(cc.items(), key=lambda x: x[1])[0] for u, cc in agg.items()}
        key = {k: cod[v] for k, v in USINA_COD.items() if v in cod}
        out = {"cod": cod, "key": key}
    except Exception as e:
        print(f"[ronda-whats] causa map (book) falhou: {e}")
        return c["data"] or out
    c.update({"ts": now, "data": out})
    return out


def _ronda_anota_causa(rows):
    """Marca r['causa_reportada'] com a causa do book (campo), casando a usina por código OU usina_key."""
    cm = _ronda_causa_map()
    cod, key = cm.get("cod") or {}, cm.get("key") or {}
    if not cod and not key:
        return
    for r in rows:
        tn = _usina_key(r.get("usina") or "")
        if not tn:
            continue
        causa = cod.get(tn) or next((v for k, v in key.items()
                                     if len(k) >= 4 and (k == tn or k in tn or tn in k)), None)
        if causa:
            r["causa_reportada"] = causa


_NOTAS_TRK_PATH  = os.path.join(_AQUI, "trackers_notas.json")
# Override LOCAL (fora do git): notas escritas NESTA máquina. Aqui o override SOMA ao versionado
# (tracker a tracker, local ganha no empate) — nota é edição incremental, não export inteiro.
_NOTAS_TRK_LOCAL = os.path.join(_AQUI, "trackers_notas.local.json")
_notas_trk_cache = {"mtime": -1, "data": {}}


def _ronda_notas_map():
    """Notas manuais de tracker por UFV (causa de campo já conhecida) → aparecem na linha do tracker na
    ronda. trackers_notas.json (+ .local.json, que soma por cima): {"UFV (como aparece na ronda)":
    {"<nº do tracker>": "nota"}}. Relido no mtime — dá p/ adicionar/editar notas SEM reiniciar o
    servidor. {} se nenhum dos dois existe/quebra."""
    mts = []
    for p in (_NOTAS_TRK_PATH, _NOTAS_TRK_LOCAL):
        try:
            mts.append(os.path.getmtime(p))
        except OSError:
            mts.append(None)
    if all(x is None for x in mts):
        return {}
    m = tuple(mts)
    c = _notas_trk_cache
    if m != c["mtime"]:
        try:
            data, obs = {}, {}
            for p, mt in zip((_NOTAS_TRK_PATH, _NOTAS_TRK_LOCAL), mts):   # local por último = ganha
                if mt is None:
                    continue
                with open(p, encoding="utf-8") as f:
                    raw = json.load(f) or {}
                for usina, notas in raw.items():
                    if str(usina).startswith("_") or not isinstance(notas, dict):
                        continue                               # "_comentario" e afins são ignorados
                    un = _tk_norm(usina)
                    por_num = {}
                    for k, v in notas.items():
                        # "_obs" = observação da USINA INTEIRA (aparece no cabeçalho da ronda). Serve
                        # pro caso "todos os trackers parados", em que o texto COLAPSA numa linha só e
                        # nota por tracker nunca seria exibida.
                        if str(k).strip().lower() in ("_obs", "_usina", "_observacao") and v:
                            if un:
                                obs[un] = str(v)
                            continue
                        dig = re.sub(r"\D", "", str(k))
                        if dig and v:
                            por_num[int(dig)] = str(v)
                    if un and por_num:
                        data.setdefault(un, {}).update(por_num)
            c["mtime"] = m; c["data"] = data; c["obs"] = obs
        except Exception as e:
            print(f"[ronda] trackers_notas falhou: {e}")
            return c["data"]
    return c["data"]


def _ronda_obs_usina(usina):
    """Observação da USINA p/ a ronda (chave `_obs` no trackers_notas[.local].json). Casa por SUBSTRING
    normalizada, então uma entrada "Fernandópolis" cobre os 3 registros (1/2/3) que a API PV separa."""
    _ronda_notas_map()                       # garante o cache carregado/atualizado pelo mtime
    obs = _notas_trk_cache.get("obs") or {}
    if not obs:
        return None
    un = _tk_norm(usina)
    for chave, txt in obs.items():
        if chave and (chave in un or un in chave):
            return txt
    return None


def _ronda_rsu_aberto(usina):
    """Observação AUTOMÁTICA de RSU (Levi 22/07): se a usina tem chamado de RSU EM ABERTO na planilha de
    Tickets (aba Trackers, Equipamento~RSU + 'Fim da ocorrência' vazio → TICKETS_RSU_ABERTO), devolve a
    linha p/ a ronda; senão None. Casa por SUBSTRING normalizado igual ao `_obs` manual (uma entrada
    "fernandópolis" cobre Fernandópolis 1/2/3 da API PV). A nota manual `_obs` tem precedência sobre esta."""
    if not TICKETS_RSU_ABERTO:
        return None
    un = _tk_norm(usina or "")
    if not un:
        return None
    for chave, info in TICKETS_RSU_ABERTO.items():
        if chave and (chave in un or un in chave):
            desde = (info or {}).get("desde")
            return "Falha na RSU — chamado em aberto na planilha de tickets" + (f" (desde {desde})" if desde else "")
    return None


def _tracker_nota(usina, tracker):
    """Nota da UFV+tracker (casa usina por substring normalizada + nº do tracker). '' se não houver."""
    nm = _ronda_notas_map()
    if not nm:
        return ""
    un = _tk_norm(usina or ""); tn = _trk_id_num(tracker)
    if tn is None:
        return ""
    for k, notas in nm.items():
        if (k in un or un in k) and tn in notas:
            return notas[tn]
    return ""


def _ronda_bloco_usinas(rs, ind="", mark="•"):
    out = []
    forcar = [_nrm(x) for x in (_whats_cfg().get("todos_parados_usinas") or []) if str(x).strip()]  # UFVs forçadas a "todos parados" (whats_ronda.json, Levi 17/07)
    esconder_inv = [_nrm(x) for x in (_whats_cfg().get("ocultar_inversor_usinas") or []) if str(x).strip()]  # UFVs que NÃO mostram o inversor na linha do tracker (Levi 23/07: Altair, Brodowski)
    for u in sorted({str(r.get("usina") or "?") for r in rs}):
        g = [r for r in rs if str(r.get("usina") or "?") == u]
        # causa já reportada no campo (book): anota no cabeçalho da usina (ex.: "— causa reportada: vegetação")
        causa_u = next((r.get("causa_reportada") for r in g if r.get("causa_reportada")), None)
        cab = f"{ind}📍 {u}  ({len(g)})"
        if causa_u:
            cab += f"  — causa reportada (campo): {causa_u}"
        out.append(cab)
        # observação da USINA (trackers_notas[.local].json → "_obs"): vai LOGO ABAIXO do cabeçalho,
        # antes de qualquer colapso ("Todos os trackers parados"), senão nunca apareceria nesse caso.
        _obs_u = _ronda_obs_usina(u) or _ronda_rsu_aberto(u)   # nota manual (_obs) ganha; senão, RSU automático da planilha
        if _obs_u:
            out.append(f"{ind}📌 {_obs_u}")
        # UFV forçada a "todos parados" (config todos_parados_usinas) — colapsa mesmo que a régua automática
        # (alvo=None em todos) não pegue. Casa por substring normalizado (ex.: "SMP100", "JCD100").
        if forcar and any(e in _nrm(u) or _nrm(u) in e for e in forcar):
            out.append(f"{ind}{mark} Todos os trackers parados")
            continue
        # usina TODA sem comunicação → 1 linha (não adianta ângulo/alvo: o logger não reporta nada).
        if len(g) > 1 and all(r.get("sem_comunicacao") for r in g):
            out.append(f"{ind}{mark} Todos os trackers sem comunicação")
            continue
        # usina TODA parada → resume em 1 linha em vez de listar tudo. Sinal: o _trk_alvo_mediana zera o
        # alvo (→ '—') SÓ quando ninguém gira, então alvo=None em TODOS os parados ⟺ usina inteira parada.
        if len(g) > 1 and all(r.get("alvo") is None for r in g):
            out.append(f"{ind}{mark} Todos os trackers parados")
            continue
        esc_inv = bool(esconder_inv) and any(e in _nrm(u) or _nrm(u) in e for e in esconder_inv)  # oculta o inversor nesta UFV?
        for r in g:
            inv = "" if esc_inv else (f" — {r['inversor']}" if r.get("inversor") else "")
            nota = _tracker_nota(r.get("usina"), r.get("tracker"))
            nt = f"  📌 {nota}" if nota else ""      # nota manual de campo (trackers_notas.json)
            if r.get("sem_comunicacao"):     # comm-morta: sem leitura confiável → só a observação
                out.append(f"{ind}{mark} {r.get('tracker')}{inv}  (sem comunicação){nt}")
            else:
                out.append(f"{ind}{mark} {r.get('tracker')}{inv}  (atual {_ronda_ang(r.get('atual'))} · alvo {_ronda_ang(r.get('alvo'))}){nt}")
    return out


def _ronda_texto_regiao(reg, rows, quando, alerta="", acomp_rows=None):
    _ronda_anota_causa(rows)                                  # cruza a causa já reportada no campo (book)
    novos = [r for r in rows if not r.get("em_garantia")]     # acionáveis (reset)
    gar   = [r for r in rows if r.get("em_garantia")]         # já com chamado aberto (não precisa reset)
    n = len(novos)
    def _acomp_lines():                                       # "em acompanhamento da performance" (já na planilha de tickets): UFV + qtd
        if not acomp_rows:
            return []
        por_u = {}
        for r in acomp_rows:
            u = str(r.get("usina") or "?")
            por_u[u] = por_u.get(u, 0) + 1
        out = ["", f"📋 ── EM ACOMPANHAMENTO DA PERFORMANCE (já na planilha de tickets · não precisa reset) · {sum(por_u.values())} ──"]
        out += [f"• {u}  ({por_u[u]})" for u in sorted(por_u)]
        return out
    linhas = [f"☀️ RONDA DE TRACKERS PARADOS — {reg.upper()} — {quando}",
              "ℹ️ Se após o reset o tracker NÃO voltar a operar, avise neste grupo para o time de "
              "Performance abrir uma Ordem de Serviço de inspeção."]
    if alerta:
        linhas.append(f"⚠️ {alerta}")
    linhas.append("")
    if not novos and not gar:
        linhas.append("✅ Nenhum tracker parado agora.")
        linhas.extend(_acomp_lines())
        return "\n".join(linhas)
    if novos:
        linhas.append(f"🔴 ═══ {reg.upper()} · {n} parado{'s' if n != 1 else ''} ═══")
        if reg == "Sudeste":                          # maior região → sub-divide por cliente/carteira
            por_cli = {}
            for r in novos:
                por_cli.setdefault(r.get("cliente") or "—", []).append(r)
            for c in sorted(por_cli):
                linhas.append(f"\n🏢 {c}  ({len(por_cli[c])})")
                linhas.extend(_ronda_bloco_usinas(por_cli[c], "    "))
        else:
            linhas.extend(_ronda_bloco_usinas(novos))
    else:
        linhas.append("✅ Nenhum tracker parado NOVO (fora os já em garantia abaixo).")
    if gar:                                           # separado: não polui os acionáveis, mas não some
        linhas.append("")
        linhas.append(f"🔧 ── JÁ EM GARANTIA (chamado aberto) · {len(gar)} — não precisa reset ──")
        linhas.extend(_ronda_bloco_usinas(gar))
    linhas.extend(_acomp_lines())
    return "\n".join(linhas)


def _whats_send(cfg, grupo_id, texto):
    r = _http().post(cfg.get("service_url", "http://127.0.0.1:5099").rstrip("/") + "/send",
                     json={"para": grupo_id, "texto": texto},
                     headers={"x-token": cfg.get("token", "")}, timeout=90)
    try:
        ok = r.status_code == 200 and bool((r.json() or {}).get("ok"))
    except Exception:
        ok = False
    return ok, (r.text or "")[:200]


def _ronda_whats_disparo(slot_label, so_regiao=None, destino=None, pular_regioes=None, confirmar=True):
    """destino: override do id de envio (ex.: número do Levi p/ testar o FORMATO sem incomodar o grupo
    real; None = grupos do config). pular_regioes: regiões JÁ enviadas com sucesso neste slot — NÃO
    reenvia (evita duplicar quem já recebeu na retentativa). confirmar: envia o resumo p/ o admin."""
    cfg = _whats_cfg()
    grupos = cfg.get("grupos") or {}
    if not grupos:
        return {"ok": False, "erro": "sem grupos no whats_ronda.json"}
    pular = set(pular_regioes or ())
    rows, falhas, acomp = _ronda_parados_all(force=True)
    quando = datetime.now().strftime("%d/%m/%Y %H:%M")
    alerta = ("ATENÇÃO: ronda incompleta — sem resposta de " + ", ".join(falhas)) if falhas else ""
    por_reg, acomp_reg = {}, {}
    for r in rows:
        por_reg.setdefault(r.get("regiao") or "Sem região", []).append(r)
    for r in acomp:
        acomp_reg.setdefault(r.get("regiao") or "Sem região", []).append(r)
    resultados = {}
    # GAP anti-spam ENTRE grupos (Levi 14/07: a conta foi restringida por "spam" = os 5 grupos quase juntos).
    # Envia em SEQUÊNCIA com intervalo aleatório (jitter) p/ não parecer blast. gap_grupos_seg no whats_ronda.json
    # (default 60s → ~42-78s por grupo). Reduz MUITO o risco, mas não zera (whatsapp-web.js é não-oficial).
    alvos = [(reg, gid) for reg, gid in grupos.items()
             if not (so_regiao and reg != so_regiao) and reg not in pular]
    gap = cfg.get("gap_grupos_seg", 60)
    for i, (reg, gid) in enumerate(alvos):
        texto = _ronda_texto_regiao(reg, por_reg.get(reg, []), quando, alerta, acomp_reg.get(reg, []))
        try:
            ok, det = _whats_send(cfg, destino or gid, texto)
        except Exception as e:
            ok, det = False, str(e)
        resultados[reg] = {"ok": ok, "trackers": len(por_reg.get(reg, [])),
                           "detalhe": None if ok else det}
        _whats_log_add(slot=slot_label, regiao=reg, ok=ok, trackers=len(por_reg.get(reg, [])),
                       erro=(None if ok else str(det)[:160]), teste=bool(destino))
        # PERSISTE INCREMENTAL: a região enviada com OK entra no estado/disco NA HORA — não só quando o
        # disparo inteiro retorna. Se o disparo CRASHAR no meio (serviço WhatsApp instável, ex.: caiu às
        # 08:22 de 20/07), quem JÁ recebeu não é reenviado na retentativa. Era a causa da RONDA DOBRADA:
        # o disparo mandava o Norte, crashava, o loop não gravava (só grava no fim) e a retentativa
        # reenviava o Norte. Só no disparo REAL (destino=None = grupos do config; teste não conta).
        if ok and not destino:
            try:
                _kk = datetime.now().strftime("%Y-%m-%d") + "|" + slot_label
                _whats_state["enviados"][_kk] = sorted(set(_whats_state["enviados"].get(_kk, [])) | {reg})
                _whats_sent_save(_whats_state["enviados"])
            except Exception:
                pass
        print(f"[ronda-whats] {slot_label} → {reg}: {'OK' if ok else 'FALHOU ' + str(det)}")
        # espera entre grupos (jitter). Só no disparo real e entre grupos (não no teste, não após o último).
        if gap and not destino and i < len(alvos) - 1:
            try:
                time.sleep(random.uniform(gap * 0.7, gap * 1.3))
            except Exception:
                pass
    # confirmação p/ o admin (pedido do Levi 06/07): resumo do que foi enviado, no número dele.
    # Em teste com destino override, só confirma se o destino É o próprio admin (senão duplica).
    conf = (cfg.get("confirmar_para") or "").strip()
    if confirmar and conf and resultados and (not destino or str(destino).replace("+", "").replace(" ", "") == conf):
        ok_n = sum(1 for v in resultados.values() if v["ok"])
        lin = [f"✅ Ronda {slot_label} · {quando} — {ok_n}/{len(resultados)} grupo(s) OK"]
        for reg, v in sorted(resultados.items()):
            lin.append((" • ✅ " if v["ok"] else " • ❌ ") + f"{reg}: {v['trackers']} tracker(s)"
                       + ("" if v["ok"] else f" — FALHOU: {str(v['detalhe'])[:80]}"))
        if falhas:
            lin.append("⚠️ Fontes sem resposta: " + ", ".join(falhas))
        try:
            _whats_send(cfg, conf, "\n".join(lin))
        except Exception as e:
            print(f"[ronda-whats] confirmação p/ admin falhou: {e}")
    return {"ok": bool(resultados) and all(v["ok"] for v in resultados.values()),
            "resultados": resultados, "fontes_falharam": falhas}


RONDA_GRACE_MIN = 120  # min após o horário do slot em que a ronda ainda DISPARA/retenta. Era 15 → o slot
#                        era PERDIDO em silêncio se o app estivesse reiniciando dentro da janela (foi o que
#                        mordeu 22/07: 3 restarts na janela das 13:00 = ronda da tarde não saiu). Agora
#                        TOLERA atraso (teto ~2h): app que sobe atrasado ainda manda o slot do dia se não
#                        passou do teto — e ainda respeita o anti-duplicação (não reenvia quem já recebeu).
#                        Configurável em whats_ronda.json > "ronda_grace_min" (relido a cada ciclo, sem restart).

# ── Log de envios da ronda (alimenta o Monitor da Ronda) ─────────────────────────────────────────
# Cada tentativa de envio por região vira uma linha {ts, slot, regiao, ok, trackers, erro};
# o watchdog também registra os restarts. Persistido (sobrevive a restart), capado em 400 linhas.
_WHATS_LOG_PATH = os.path.join(_AQUI, "whats_log.json")
_whats_log = []
try:
    with open(_WHATS_LOG_PATH, encoding="utf-8") as _f:
        _whats_log = json.load(_f) or []
except Exception:
    _whats_log = []


def _whats_log_add(**e):
    e["ts"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    _whats_log.append(e)
    del _whats_log[:-400]
    try:
        with open(_WHATS_LOG_PATH, "w", encoding="utf-8") as f:
            json.dump(_whats_log, f, ensure_ascii=False)
    except Exception as ex:
        print(f"[ronda-whats] log não salvo: {ex}")


def _ronda_whats_loop():
    """Dispara nos horários do config. CORREÇÃO 08/07 (Levi: a ronda das 08:25 falhou — navegador do
    whatsapp-web.js travou — mas o estado marcou 'enviado' e não retentou): marca 'ok' SÓ depois do
    envio CONFIRMAR (o loop é síncrono → o disparo bloqueia, não há overlap); se falhar, RETENTA a
    cada 30s até RONDA_GRACE_MIN após o horário. Assim o status reflete a verdade e um serviço que
    piscou é reenviado. enabled=false = dormindo."""
    time.sleep(120)                                   # deixa o boot aquecer caches
    while True:
        try:
            cfg = _whats_cfg()
            if cfg.get("enabled"):
                # RE-LÊ o disco e MESCLA na memória A CADA CICLO (antes era só no boot). Se uma 2ª instância
                # do app estiver de pé (o guardião às vezes sobe outra), ela já persistiu as regiões que
                # enviou neste slot → esta cópia enxerga e NÃO reenvia. Era a causa da RONDA DOBRADA
                # (Levi 20/07: dois lotes ~10min separados; cada processo só tinha o _whats_state do próprio
                # boot, os dois disparavam o mesmo slot). O disco é a fonte da verdade compartilhada.
                for _k, _v in _whats_sent_load().items():
                    _whats_state["enviados"][_k] = sorted(set(_whats_state["enviados"].get(_k, [])) | set(_v))
                agora = datetime.now()
                hoje = agora.strftime("%Y-%m-%d")
                now_min = agora.hour * 60 + agora.minute
                todas_regs = set((cfg.get("grupos") or {}).keys())
                try:                                          # teto de atraso (default RONDA_GRACE_MIN=120min);
                    grace = max(1, int(cfg.get("ronda_grace_min", RONDA_GRACE_MIN)))   # ajustável no json sem restart
                except Exception:
                    grace = RONDA_GRACE_MIN
                for slot in (cfg.get("horarios") or []):
                    key = hoje + "|" + slot
                    ja = set(_whats_state["enviados"].get(key, []))
                    if todas_regs and ja >= todas_regs:
                        continue                       # slot COMPLETO (todos os grupos) → nada a fazer
                    try:
                        _sh, _sm = map(int, slot.split(":")); slot_min = _sh * 60 + _sm
                    except Exception:
                        continue
                    if slot_min <= now_min <= slot_min + grace:
                        # envia SÓ os grupos que ainda NÃO receberam (nunca reenvia quem já recebeu na
                        # retentativa) e persiste em disco (restart no meio da janela não reenvia).
                        res = _ronda_whats_disparo(slot, pular_regioes=ja, confirmar=False)
                        novos = [r for r, v in (res.get("resultados") or {}).items() if v.get("ok")]
                        if novos:
                            ja |= set(novos)
                            _whats_state["enviados"][key] = sorted(ja)
                            _whats_sent_save(_whats_state["enviados"])
                        if todas_regs and ja >= todas_regs:
                            print(f"[ronda-whats] {slot} enviada OK (todos os {len(todas_regs)} grupos)")
                            conf = (cfg.get("confirmar_para") or "").strip()
                            if conf:                   # resumo p/ o admin 1x só (slot já fica marcado)
                                ffalh = res.get("fontes_falharam") or []
                                msg = (f"✅ Ronda {slot} enviada · {agora:%d/%m/%Y %H:%M} — "
                                       f"{len(todas_regs)} grupos OK"
                                       + (f"\n⚠️ Fontes sem resposta: {', '.join(ffalh)}" if ffalh else ""))
                                try: _whats_send(cfg, conf, msg)
                                except Exception: pass
                        else:
                            print(f"[ronda-whats] {slot} parcial — faltam {sorted(todas_regs - ja)}, "
                                  f"retenta até +{grace}min")
                        break                          # 1 disparo por ciclo (é síncrono, evita 2 slots juntos)
        except Exception as e:
            print(f"[ronda-whats] loop: {e}")
        time.sleep(30)


def _whats_service_restart():
    """Reergue o serviço WhatsApp (C:\\GridcoWhats): mata os chromes ZUMBIS do GridcoWhats + o node,
    remove o lock do perfil e relança o node. O kill fica no PowerShell (funciona), mas o LANÇAMENTO
    é subprocess.Popen DIRETO — Start-Process via powershell-filho falha com 'arquivo não encontrado'
    (descoberto 09/07: o watchdog 'reiniciava' e nada subia). True se o node foi lançado."""
    ps = (
        "Get-CimInstance Win32_Process -Filter \"name='chrome.exe'\" | "
        "Where-Object { $_.CommandLine -match 'GridcoWhats' } | "
        "ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }; "
        "Get-CimInstance Win32_Process -Filter \"name='node.exe'\" | "
        "Where-Object { $_.CommandLine -match 'wa_service' } | "
        "ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }"
    )
    try:
        # CREATE_NO_WINDOW: não pisca janela de console ao chamar o powershell (rodamos sob pythonw).
        subprocess.run(["powershell", "-NoProfile", "-Command", ps], timeout=45, capture_output=True,
                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
    except Exception as e:
        print(f"[whats-watchdog] kill de zumbis falhou (segue p/ o relance): {e}")
    time.sleep(2)
    try:
        os.remove(r"C:\GridcoWhats\session\session\lockfile")
    except OSError:
        pass
    try:
        # DETACHED (0x8) + NO_WINDOW: o node vive independente do Flask (restart nosso não o derruba).
        out = open(r"C:\GridcoWhats\wa_service.out.log", "w")
        err = open(r"C:\GridcoWhats\wa_service.err.log", "w")
        subprocess.Popen([r"C:\Program Files\nodejs\node.exe", "wa_service.js"],
                         cwd=r"C:\GridcoWhats", stdout=out, stderr=err, stdin=subprocess.DEVNULL,
                         creationflags=0x00000008 | getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000))
        return True
    except Exception as e:
        print(f"[whats-watchdog] relance do node falhou: {e}")
        return False


_whats_wd_state = {"ultimo_restart": 0.0, "restarts_hoje": 0, "dia": "", "notif_pend": None}


def _whats_watchdog_loop():
    """Vigia o serviço WhatsApp: a cada 3 min sonda /health (getState ATIVO — pega o 'detached Frame'
    que o /status esconde). QUEBRADO + enabled → reergue o serviço sozinho NA HORA. A notificação ao
    admin sai no PRÓXIMO ciclo já saudável (a sessão precisa re-sincronizar o LID do nº avulso após o
    restart; enviar na hora cai em erro silencioso). Cooldown de 5 min entre restarts. Criado 08/07
    após 2 quedas no dia (08:25 e 13:15 — navegador do whatsapp-web.js travou e a ronda falhou calada)."""
    time.sleep(200)                                   # não concorre com o boot
    while True:
        try:
            cfg = _whats_cfg()
            if cfg.get("enabled"):
                url = cfg.get("service_url", "http://127.0.0.1:5099").rstrip("/")
                tok = cfg.get("token", "")
                try:
                    h = _http().get(url + "/health", headers={"x-token": tok}, timeout=15)
                    broken = (h.status_code != 200) or (not (h.json() or {}).get("ok"))
                except Exception:
                    broken = True                     # timeout/sem resposta = travado ou caído
                agora = time.time()
                if broken and (agora - _whats_wd_state["ultimo_restart"]) > 300:
                    print("[whats-watchdog] serviço QUEBRADO (health falhou) — reiniciando...")
                    _whats_wd_state["ultimo_restart"] = agora
                    hoje = datetime.now().strftime("%Y-%m-%d")
                    if _whats_wd_state["dia"] != hoje:
                        _whats_wd_state.update({"dia": hoje, "restarts_hoje": 0})
                    _whats_wd_state["restarts_hoje"] += 1
                    _whats_service_restart()
                    _whats_log_add(slot="watchdog", regiao=None, ok=False, trackers=None,
                                   erro="serviço WhatsApp travou — reiniciado automaticamente")
                    _whats_wd_state["notif_pend"] = (datetime.now().strftime("%H:%M"),
                                                     _whats_wd_state["restarts_hoje"])
                elif _whats_wd_state["notif_pend"] and not broken:
                    # serviço saudável de novo (sessão já aquecida) → agora sim avisa o admin
                    quando, n = _whats_wd_state["notif_pend"]
                    conf = (cfg.get("confirmar_para") or "").strip()
                    if conf:
                        try:
                            _whats_send(cfg, conf, f"[watchdog] O serviço da ronda TRAVOU (navegador) "
                                        f"por volta das {quando} e foi reiniciado automaticamente. "
                                        f"Envios já normalizados (restart nº {n} hoje).")
                        except Exception:
                            pass
                    _whats_wd_state["notif_pend"] = None
        except Exception as e:
            print(f"[whats-watchdog] loop: {e}")
        time.sleep(180)


